PROGRAM PRG_base
VAR
 	//Время выполнения программы
	result_time:ULINT;
	/// Признак первого вызова программы
	init: BOOL := TRUE;
END_VAR
VAR_TEMP
	start_time:ULINT;
	end_time:ULINT;
END_VAR

PROGRAM PRG_base
VAR
 	//Время выполнения программы
	result_time:ULINT;
	/// Признак первого вызова программы
	init: BOOL := TRUE;
END_VAR
VAR_TEMP
	start_time:ULINT;
	end_time:ULINT;
END_VAR

ST.xhtml:
start_time:= PsTimeGetUtcTimeNs(); // Время начала выполнения
//==============================================================================================

IF init THEN
	fun_init();
	init := FALSE;
END_IF

//Кнопки
btn_update();

// Настройки
tunpar_update();

// Таймеры
tmr_update();

// ИМ-ы
// Конфигуратор
am_update();
// Создан вручную
am_update_base();

//Алгоритм
ALG_base();				//Алгоритм

aggregation_am();

// Формирование тестовых сигналов
test.Saw_Slow();
test.Sin_Slow();

//==============================================================================================
end_time:=PsTimeGetUtcTimeNs() ;  // конец
result_time:=end_time-start_time;  // время выполнения фрагмента кода

