PROGRAM PRG_fast
VAR
 	//Время выполнения программы
	result_time:ULINT;
END_VAR
VAR_TEMP
	start_time:ULINT;
	end_time:ULINT;
END_VAR

ST.xhtml:
start_time:=PsTimeGetUtcTimeNs(); // Время начала выполнения
//==============================================================================================

////// Временно здесь
//{warning ' Убрать на новой версии макроса '}
//aipar.common.sim_aggregated	:= FALSE;
//aopar.common.sim_aggregated	:= FALSE;
//dipar.common.sim_aggregated	:= FALSE;
//dopar.common.sim_aggregated	:= FALSE;
/////////////

// Сброс переменных VAR_STAT
// По входам / выходам
reset_io_var_stat();
// По сигнализациям
reset_alarm_var_stat();
// По ИМам
reset_am_var_stat();

// Ввод
	aipar_update(cycle := cycle_time_fast);		//Вызов обработки всех экземпляров AI быстрого цикла
	dipar_update();								//Вызов обработки всех экземпляров DI быстрого цикла

	MODULE_UCP1_A1_AI6.T_JUNCTION := aipar.Tcool.value; // компенсация холодного спая
	MODULE_UCP1_A1_AI7.T_JUNCTION := aipar.Tcool.value; // компенсация холодного спая
//---------------------------------------------------------------------------------------------

// Расчётные параметры
	acpar_handler.handler(cycle := cycle_time_fast);

	acpar_update(); 							//Обработка расчётных параметров (Формирование уставок)
//---------------------------------------------------------------------------------------------	

// Сигнализации
	Alarm_link(); //Подготовка данных и вызов обработчиков сигнализаций
//Агрегация сигнализаций (все сигнализации должны быть вызваны к этому моменту)
	aggregation_alarms();
//---------------------------------------------------------------------------------------------	

// Топливный регулятор
	FR_link();
	AS_Link();

// Быстрые ИМ-ы
	ALG_D_AM_fast();
	// Создан вручную
	am_update_fast();
	// аналоговые
	// Конфигуратор
	ama_update();

//Сигналы контроллера
	ALG_PLC();

// Вывод
	aopar_update(); 							//Вызов обработки всех экземпляров AO быстрого цикла
	dopar_update(); 							//Вызов обработки всех экземпляров DO быстрого цикла
//---------------------------------------------------------------------------------------------	
// IEC 104

// Формирование тестовых сигналов
	test.Saw_Fast();
// IEC-104
	IEC104_update();

//==============================================================================================
end_time:=PsTimeGetUtcTimeNs() ;  // конец
result_time:=end_time-start_time;  // время выполнения фрагмента кода

