dopar.VVN_off.value := am.VVN.offOUT;

//Имитацию включить
btn.imit_ON.prm := mde.Repair;
btn.imit_ON();

//Имитацию выключить
btn.imit_OF.prm := TRUE;
btn.imit_OF();

//Тестирование включить
btn.test_on.prm := mde.Repair;
btn.test_on();

//Тестирование выключить
btn.test_off.prm := TRUE;
btn.test_off();

//Ремонт
btn.Repair.prm := alg.V_000 AND NOT tch.PrepareStart.value;
btn.Repair();

//Холодный резерв
btn.HR.prm := ( mde.Repair OR mde.GR ) AND NOT tch.PrepareStart.value AND NOT tch.CheckAlarm_on.Value ;
btn.HR();

//Горячий резерв
btn.GR.prm := mde.Repair OR mde.HR AND NOT tch.CheckAlarm_on.Value ;
btn.GR();

//Комплексная проверка кранов
btn.KPK.prm := mde.GR AND NOT ( tch.PrepareStart.value OR tch.Gas_N.value );
btn.KPK();

//Холодная прокрутка
btn.HP.prm := mde.GR AND NOT tch.PrepareStart.value;
btn.HP();

//Автоматический пуск на Кольцо
btn.APK.prm := mde.GR AND NOT tch.PrepareStart.value;
btn.APK();

//Пуск
btn.Start.prm := check.ReadytoSF AND check.prm_start;
btn.Start();

//Отмена
btn.Cancel.prm := check.ReadytoSF OR mde.Repair OR check.tmrCancelPrm.Q;
btn.Cancel();

//Контроль САУ
btn.Check_SAU.prm := TRUE;
btn.Check_SAU();

//Переход Магистраль-Кольцо
btn.M_K.prm := mde.M OR mde.K_M;
btn.M_K();

//Переход Кольцо-Магистраль
btn.K_M.prm := mde.K OR mde.M_K;
btn.K_M();

//Нормальный останов со стравливанием
btn.NOss.prm := alg.work OR mde.NObs;
btn.NOss();

//Нормальный останов без стравливания
btn.NObs.prm := alg.work;
btn.NObs();

//Аварийный останов со стравливанием
btn.AOss.prm := TRUE;
btn.AOss();

//Аварийный останов без стравливания
btn.AObs.prm := NOT mde.AOss;
btn.AObs();

//Деблокировка
btn.Unlock.prm := TRUE;
btn.Unlock();

//РЧВ: вверх
btn.turnUP.prm := tch.GTDwork.value;
btn.turnUP();

//РЧВ: вниз
btn.turnDN.prm := tch.GTDwork.value;
btn.turnDN();

//Запись настроек регулятора
btn.set_tun.prm := NOT btn.get_tun.out;
btn.set_tun();

//Считывание настроек регулятора
btn.get_tun.prm := NOT btn.set_tun.out;
btn.get_tun();

//Стравливание
btn.bleeding.prm := alg.V_000;
btn.bleeding();

//Проверку защит включить
btn.CheckAlarm_on.prm := mde.Repair;
btn.CheckAlarm_on();

//Проверку защит выключить
btn.CheckAlarm_off.prm := mde.Repair;
btn.CheckAlarm_off();

alg.AOss_tech := FALSE;
alg.AObs_tech := FALSE;
alg.VOss_tech := FALSE;

IF
	   (mde.AObs) AND (alg.AOss) //Переход: АОбс->АОсс
	OR (mde.NOss) AND (alg.AOss OR alg.AObs) //Переход: НОсс->АОсс
	OR (mde.NObs) AND (alg.AOss) //Переход: НОбс->АОсс
	OR (mde.Repair) AND (alg.AOss AND tch.Gas_N.value) //Переход: Ремонт->АОсс
	OR (mde.HR) AND (alg.AOss AND tch.Gas_N.value) //Переход: ХР->АОсс
	OR (mde.GR) AND (alg.AOss AND tch.Gas_N.value) //Переход: ГР->АОсс
	OR (mde.AObs) AND (alg.AOss OR alg.AObs AND tch.nGas_N.value) //Переход: АОбс->АОсс
	OR (mde.PZ) AND (alg.AOss OR alg.AObs AND tch.nGas_N.value) //Переход: ПЗ->АОсс
	OR (mde.HP) AND (alg.AOss OR alg.AObs AND tch.nGas_N.value) //Переход: ХП->АОсс
	OR (mde.KPK) AND (alg.AOss OR alg.AObs AND tch.nGas_N.value) //Переход: КПК->АОсс
	OR (mde.APK) AND (alg.AOss OR alg.AObs AND tch.nGas_N.value) //Переход: АПК->АОсс
	OR (mde.K) AND (alg.AOss) //Переход: Кольцо->АОсс
	OR (mde.M) AND (alg.AOss) //Переход: Магистраль->АОсс
	OR (mde.K_M) AND (alg.AOss) //Переход: Переход К-М->АОсс
	OR (mde.M_K) AND (alg.AOss) //Переход: Переход М-К->АОсс
					THEN mde.number := enum_mode.AOss;

		IF
		   (mde.NOss) AND (alg.AObs)
		OR (mde.AObs) AND (alg.AObs AND tch.nGas_N.value)
		OR (mde.PZ) AND (alg.AObs AND tch.nGas_N.value)
		OR (mde.HP) AND (alg.AObs AND tch.nGas_N.value)
		OR (mde.KPK) AND (alg.AObs AND tch.nGas_N.value)
		OR (mde.APK) AND (alg.AObs AND tch.nGas_N.value)
					THEN alg.AOss_tech := TRUE;
		END_IF;
ELSIF
	   (mde.NObs) AND (alg.AObs) //Переход: НОбс->АОбс
	OR (mde.HP) AND (alg.AObs) //Переход: ХП->АОбс
	OR (mde.KPK) AND (alg.AObs) //Переход: КПК->АОбс
	OR (mde.APK) AND (alg.AObs) //Переход: АПК->АОбс
	OR (mde.K) AND (alg.AObs) //Переход: Кольцо->АОбс
	OR (mde.M) AND (alg.AObs) //Переход: Магистраль->АОбс
	OR (mde.K_M) AND (alg.AObs) //Переход: Переход К-М->АОбс
	OR (mde.M_K) AND (alg.AObs) //Переход: Переход М-К->АОбс
					THEN mde.number := enum_mode.AObs;
ELSIF
	   (mde.NObs) AND (btn.NOss.out) //Переход: НОбс->НОсс
	OR (mde.K) AND (btn.NOss.out) //Переход: Кольцо->НОсс
	OR (mde.M) AND (btn.NOss.out) //Переход: Магистраль->НОсс
	OR (mde.K_M) AND (btn.NOss.out) //Переход: Переход К-М->НОсс
	OR (mde.M_K) AND (btn.NOss.out) //Переход: Переход М-К->НОсс
					THEN mde.number := enum_mode.NOss;
ELSIF
	   (mde.K) AND (btn.NObs.out) //Переход: Кольцо->НОбс
	OR (mde.M) AND (btn.NObs.out) //Переход: Магистраль->НОбс
	OR (mde.K_M) AND (btn.NObs.out) //Переход: Переход К-М->НОбс
	OR (mde.M_K) AND (btn.NObs.out) //Переход: Переход М-К->НОбс
					THEN mde.number := enum_mode.NObs;
ELSIF
	   (mde.AOss) AND (AOss.finish AND btn.Unlock.out) //Переход: АОсс->Ремонт
	OR (mde.AObs) AND (AObs.finish AND btn.Unlock.out) //Переход: АОбс->Ремонт
	OR (mde.NOss) AND (NOT ppu.HR AND NOss.finish) //Переход: НОсс->Ремонт
	OR (mde.NObs) AND (NOT ppu.HR AND NObs.finish) //Переход: НОбс->Ремонт
	OR (mde.HR) AND (NOT ppu.HR AND NOT tch.Check_SAU.value OR btn.Repair.out) //Переход: ХР->Ремонт
	OR (mde.GR) AND (NOT ppu.HR AND NOT tch.Check_SAU.value OR btn.Repair.out) //Переход: ГР->Ремонт
	OR (mde.PZ) AND (NOT ppu.HR AND (btn.Cancel.out)) //Переход: ПЗ->Ремонт
	OR (mde.HP) AND (NOT ppu.HR AND HP.finish) //Переход: ХП->Ремонт
	OR (mde.KPK) AND (NOT ppu.HR AND KPK.finish) //Переход: КПК->Ремонт
	OR (mde.Error) AND (TRUE) //Переход: …->Ремонт
					THEN mde.number := enum_mode.Repair;
ELSIF
	   (mde.NOss) AND (ppu.HR AND NOss.finish) //Переход: НОсс->ХР
	OR (mde.NObs) AND (NOT ppu.GR AND ppu.HR AND NObs.finish) //Переход: НОбс->ХР
	OR (mde.Repair) AND (ppu.HR AND ppu.Check_HR.value) //Переход: Ремонт->ХР
	OR (mde.GR) AND (ppu.HR AND NOT ppu.GR AND NOT tch.Check_SAU.value OR btn.HR.out) //Переход: ГР->ХР
	OR (mde.PZ) AND (NOT ppu.GR AND ppu.HR AND (btn.Cancel.out)) //Переход: ПЗ->ХР
	OR (mde.HP) AND (NOT ppu.GR AND ppu.HR AND HP.finish) //Переход: ХП->ХР
	OR (mde.KPK) AND (NOT ppu.GR AND ppu.HR AND KPK.finish) //Переход: КПК->ХР
					THEN mde.number := enum_mode.HR;
ELSIF
	   (mde.NObs) AND (ppu.GR AND ppu.HR AND NObs.finish) //Переход: НОбс->ГР
	OR (mde.Repair) AND (ppu.GR AND ppu.HR AND ppu.Check_GR.value) //Переход: Ремонт->ГР
	OR (mde.HR) AND (ppu.GR AND ppu.HR AND ppu.Check_GR.value) //Переход: ХР->ГР
	OR (mde.PZ) AND (ppu.GR AND ppu.HR AND (btn.Cancel.out)) //Переход: ПЗ->ГР
	OR (mde.HP) AND (ppu.GR AND ppu.HR AND HP.finish) //Переход: ХП->ГР
	OR (mde.KPK) AND (ppu.GR AND ppu.HR AND KPK.finish) //Переход: КПК->ГР
					THEN mde.number := enum_mode.GR;
ELSIF
	   (mde.GR) AND (btn.Start.out AND tch.ReadyPZ.value) //Переход: ГР->ПЗ
					THEN mde.number := enum_mode.PZ;
ELSIF
	   (mde.GR) AND (btn.Start.out AND tch.ReadyHP.value) //Переход: ГР->ХП
					THEN mde.number := enum_mode.HP;
ELSIF
	   (mde.GR) AND (btn.Start.out AND tch.ReadyKPK.value) //Переход: ГР->КПК
					THEN mde.number := enum_mode.KPK;
ELSIF
	   (mde.GR) AND (btn.Start.out AND tch.ReadyAPK.value) //Переход: ГР->АПК
					THEN mde.number := enum_mode.APK;
ELSIF
	   (mde.APK) AND (APK.finish) //Переход: АПК->Кольцо
	OR (mde.M_K) AND (M_K.finish) //Переход: Переход М-К->Кольцо
					THEN mde.number := enum_mode.K;
ELSIF
	   (mde.K_M) AND (K_M.finish) //Переход: Переход К-М->Магистраль
					THEN mde.number := enum_mode.M;
ELSIF
	   (mde.K) AND (btn.K_M.out) //Переход: Кольцо->Переход К-М
	OR (mde.M_K) AND (btn.K_M.out) //Переход: Переход М-К->Переход К-М
					THEN mde.number := enum_mode.K_M;
ELSIF
	   (mde.M) AND (btn.M_K.out) //Переход: Магистраль->Переход М-К
	OR (mde.K_M) AND (btn.M_K.out) //Переход: Переход К-М->Переход М-К
					THEN mde.number := enum_mode.M_K;
END_IF;

//------------------------------------------------------------//
mde.AOss := mde.number = enum_mode.AOss;
mde.AObs := mde.number = enum_mode.AObs;
mde.NOss := mde.number = enum_mode.NOss;
mde.NObs := mde.number = enum_mode.NObs;
mde.Repair := mde.number = enum_mode.Repair;
mde.HR := mde.number = enum_mode.HR;
mde.GR := mde.number = enum_mode.GR;
mde.PZ := mde.number = enum_mode.PZ;
mde.HP := mde.number = enum_mode.HP;
mde.KPK := mde.number = enum_mode.KPK;
mde.APK := mde.number = enum_mode.APK;
mde.K := mde.number = enum_mode.K;
mde.M := mde.number = enum_mode.M;
mde.K_M := mde.number = enum_mode.K_M;
mde.M_K := mde.number = enum_mode.M_K;
mde.Error := mde.number = enum_mode.Error;
//------------------------------------------------------------//

//Собираем переходы для визуализации drm.transition.0 := start := APK.cmd_start_D; //Запуск последовательности (0→1): АПК => Пуск двигателя drm.transition.1 := am.KR11.isOn AND am.KR10.isOff; //1→2: Кран 11 открылся, кран 10 закрылся drm.transition.2 := acpar.Ntk.value < 100.0; //2→3: Nтк < 100 об/мин drm.transition.3 := am.KR12.isON AND am.KR9.isOff; //3→4: Продувка топливного газа drm.transition.4 := aipar.Ptg_inTRK.value > 1.96 AND NOT dipar.Pm_SAR_An.value AND acpar.Ntk.value > 1800; //4→5: Давление ТГ > 20 кгс/см2 И Pm перед ДГ > 15 кгс/см2 И Ntk > 1800 об/мин drm.transition.5 := acpar.Ntk.value > 4500; //5→6: Nтк > 4500 об/мин drm.transition.6 := FuelReg.fReg.heating; //6→7: Переход двигателя в режим прогрева drm.transition.7 := NOT FuelReg.fReg.heating; //7→8: Прогрев двигателя drm.transition.8 := am.KPV1.isOff AND am.KPV5.isOff; //8→9: Закрытие КПВ drm.transition.9 := TRUE; //9→0: Логическая 1 drm.transition.31 := break := alg.AO; //Принудительный выход из последовательности (N→0): Режимы аварийного останова
//Вызываем экземпляр интерфейсного функционального блока drm(cycle := cycle);
CASE drm.step OF -1: //Сброс команд с предыдущих шагов finish := FALSE; //Условие запуска последовательности //АПК => Пуск двигателя IF start AND NOT break THEN drm.step := 1; END_IF; 1: //Запись уставки таймера шага drm.step := 1;//Текущий шаг drm.timer_pt := cycle; //Таймер: один цикл вызова
//Команды текущего шага (*1*) cmd_KR11_On := drm.cmd.0 := TRUE; //Открытие крана 11, закрытие крана 10 (*1*) drm.error.0 := am.KR11.notOn OR am.KR10.notOff; //Кран 11 не открылся, кран 10 не закрылся
//Условие перехода (1)→(2) //Кран 11 открылся, кран 10 закрылся IF (am.KR11.isOn AND am.KR10.isOff) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2; cmd_KR11_On := FALSE; //Открытие крана 11, закрытие крана 10 END_IF; 2: //Запись уставки таймера шага drm.step := 2;//Текущий шаг drm.timer_pt := cycle; //Таймер: один цикл вызова
//Команды текущего шага (*1*) check_Ntk := drm.cmd.0 := TRUE; //Проверка Nтк (*1*) drm.error.0 := acpar.Ntk.value > 100.0; //Nтк > 100 об/мин
//Условие перехода (2)→(3) //Nтк < 100 об/мин IF (acpar.Ntk.value < 100.0) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 3; check_Ntk := FALSE; //Проверка Nтк END_IF; 3: //Запись уставки таймера шага drm.step := 3;//Текущий шаг drm.timer_pt := cycle; //Таймер: один цикл вызова
//Команды текущего шага (*1*) cmd_KR12_On := drm.cmd.0 := TRUE; //Открытие крана 12, закрытие крана 9 (*1*) drm.error.0 := am.KR12.notOn OR am.KR9.notOff; //Кран 12 не открылся, кран 9 не закрылся
(*2*) cmd_VNA_On := drm.cmd.1 := TRUE; //Включение Э/М ВНА
(*3*) cmd_KPV_On := drm.cmd.2 := TRUE; //Открыть КПВ
(*4*) cmd_VS_On := drm.cmd.3 := TRUE; //Пуск воздушного стартера (*4*) drm.error.3 := am.KR13.notOn; //Кран 13 не открылся
//Условие перехода (3)→(4) //Продувка топливного газа IF (am.KR12.isON AND am.KR9.isOff) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 4; cmd_KR12_On := FALSE; //Открытие крана 12, закрытие крана 9 cmd_KPV_On := FALSE; //Открыть КПВ cmd_VS_On := FALSE; //Пуск воздушного стартера END_IF; 4: //Запись уставки таймера шага drm.step := 4;//Текущий шаг drm.timer_pt := cycle; //Таймер: один цикл вызова
//Команды текущего шага (*1*) cmd_sh_TG_On := drm.cmd.0 := TRUE; //Взвести защиту по ТГ
(*2*) cmd_SK_On := drm.cmd.1 := TRUE; //СК открыть
(*3*) starter_go := drm.cmd.2 := TRUE; //Прокрутка двигателя стартером
//Условие перехода (4)→(5) //Давление ТГ > 20 кгс/см2 И Pm перед ДГ > 15 кгс/см2 И Ntk > 1800 об/мин IF (aipar.Ptg_inTRK.value > 1.96 AND NOT dipar.Pm_SAR_An.value AND acpar.Ntk.value > 1800) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 5; cmd_sh_TG_On := FALSE; //Взвести защиту по ТГ cmd_SK_On := FALSE; //СК открыть starter_go := FALSE; //Прокрутка двигателя стартером END_IF; 5: //Запись уставки таймера шага drm.step := 5;//Текущий шаг drm.timer_pt := cycle; //Таймер: один цикл вызова
//Команды текущего шага (*1*) am.KR15.on := drm.cmd.0 := TRUE; //Открытие крана 15
(*2*) cmd_sh_nIgnition := drm.cmd.1 := TRUE; //Взвод защиты по не розжигу на пуске
(*3*) cmd_AZ_On := drm.cmd.2 := drm.step_time <= cycle; //Включение зажигания
(*4*) FuelReg.fReg.startCom := drm.cmd.3 := TRUE; //Пуск двигателя
//Условие перехода (5)→(6) //Nтк > 4500 об/мин IF (acpar.Ntk.value > 4500) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 6; cmd_sh_nIgnition := FALSE; //Взвод защиты по не розжигу на пуске cmd_AZ_On := FALSE; //Включение зажигания FuelReg.fReg.startCom := FALSE; //Пуск двигателя END_IF; 6: //Запись уставки таймера шага drm.step := 6;//Текущий шаг drm.timer_pt := 10; //Таймер: 10 секунд
//Команды текущего шага (*1*) cmd_sh_nBoost := drm.cmd.0 := drm.step_time <= cycle; //Взвод защиты по не раскрутке
(*2*) cmd_VS_Off := drm.cmd.1 := TRUE; //Останов воздушного стартера (*2*) drm.error.1 := am.KR13.notOff; //Кран 13 не закрылся
(*3*) cmd_KR11_Off := drm.cmd.2 := TRUE; //Закрытие крана 11, открытие крана 10 (*3*) drm.error.2 := am.KR11.notOff OR am.KR10.notOn; //Кран 11 не закрылся, кран 10 не открылся
(*4*) am.KR15.on := FALSE; //Кран 15 закрыть
//Условие перехода (6)→(7) //Переход двигателя в режим прогрева IF (FuelReg.fReg.heating) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 7; cmd_sh_nBoost := FALSE; //Взвод защиты по не раскрутке cmd_VS_Off := FALSE; //Останов воздушного стартера cmd_KR11_Off := FALSE; //Закрытие крана 11, открытие крана 10 END_IF; 7: //Запись уставки таймера шага drm.step := 7;//Текущий шаг drm.inc := TRUE; //Выставляем признак инкремента
//Команды текущего шага (*1*) cmd_VNA_On := FALSE; //Отключение Э/М ВНА
(*2*) cmd_PNU_Off := drm.cmd.1 := drm.step_time <= cycle; //Отключение маслонасоса уплотнения (*2*) drm.error.1 := am.PNU.notOff; //Маслонасос уплотнений не выключился
(*3*) cmd_PNS_Off := drm.cmd.2 := drm.step_time <= cycle; //Отключение маслонасоса смазки (*3*) drm.error.2 := am.PNS.notOff; //Маслонасос смазки не выключился
(*4*) cmd_KPV234_Off := drm.cmd.3 := drm.step_time <= cycle; //Закрыть КПВ 2, 3, 4 (*4*) drm.error.3 := am.KPV2.notOff AND am.KPV3.notOff AND am.KPV4.notOff; //КПВ 2, 3, 4 не закрылись
//Условие перехода (7)→(8) //Прогрев двигателя IF (NOT FuelReg.fReg.heating) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 8; cmd_PNU_Off := FALSE; //Отключение маслонасоса уплотнения cmd_PNS_Off := FALSE; //Отключение маслонасоса смазки cmd_KPV234_Off := FALSE; //Закрыть КПВ 2, 3, 4 END_IF; 8: //Запись уставки таймера шага drm.step := 8;//Текущий шаг drm.timer_pt := cycle; //Таймер: один цикл вызова
//Команды текущего шага (*1*) cmd_AZ_On := drm.cmd.0 := drm.step_time <= cycle; //Тренирование свечей зажигания
(*2*) heating_end := drm.cmd.1 := TRUE; //Прогрев двигателя окончен
(*3*) Ntk_Up := drm.cmd.2 := TRUE; //Подъём оборотов
(*4*) KPV15_close := drm.cmd.3 := TRUE; //Закрытие КПВ 1, 5 (*4*) drm.error.3 := am.KPV1.notOff AND am.KPV5.notOff; //КПВ 1, 5 не закрылись
//Условие перехода (8)→(9) //Закрытие КПВ IF (am.KPV1.isOff AND am.KPV5.isOff) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 9; cmd_AZ_On := FALSE; //Тренирование свечей зажигания heating_end := FALSE; //Прогрев двигателя окончен Ntk_Up := FALSE; //Подъём оборотов KPV15_close := FALSE; //Закрытие КПВ 1, 5 END_IF; 9: //Запись уставки таймера шага drm.step := 9;//Текущий шаг drm.timer_pt := cycle; //Таймер: один цикл вызова
//Команды текущего шага (*1*) finish := drm.cmd.0 := TRUE; //Завершение
//Условие перехода (9)→(0) //Логическая 1 IF (TRUE) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1; finish := FALSE; //Завершение END_IF; END_CASE
//Принудительный выход из последовательности IF break THEN drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; cmd_KR11_On := FALSE; //Открытие крана 11, закрытие крана 10 check_Ntk := FALSE; //Проверка Nтк cmd_KR12_On := FALSE; //Открытие крана 12, закрытие крана 9 cmd_VNA_On := FALSE; //Включение Э/М ВНА cmd_KPV_On := FALSE; //Открыть КПВ cmd_VS_On := FALSE; //Пуск воздушного стартера cmd_sh_TG_On := FALSE; //Взвести защиту по ТГ cmd_SK_On := FALSE; //СК открыть starter_go := FALSE; //Прокрутка двигателя стартером am.KR15.on := FALSE; //Открытие крана 15 cmd_sh_nIgnition := FALSE; //Взвод защиты по не розжигу на пуске cmd_AZ_On := FALSE; //Включение зажигания FuelReg.fReg.startCom := FALSE; //Пуск двигателя cmd_sh_nBoost := FALSE; //Взвод защиты по не раскрутке cmd_VS_Off := FALSE; //Останов воздушного стартера cmd_KR11_Off := FALSE; //Закрытие крана 11, открытие крана 10 cmd_PNU_Off := FALSE; //Отключение маслонасоса уплотнения cmd_PNS_Off := FALSE; //Отключение маслонасоса смазки cmd_KPV234_Off := FALSE; //Закрыть КПВ 2, 3, 4 cmd_AZ_On := FALSE; //Тренирование свечей зажигания heating_end := FALSE; //Прогрев двигателя окончен Ntk_Up := FALSE; //Подъём оборотов KPV15_close := FALSE; //Закрытие КПВ 1, 5 finish := FALSE; //Завершение END_IF;

