drm.transition.0 := start := AOss.cmd_bleeding OR NOss.cmd_bleeding OR Bleeding_full.cmd_bleeding; //Запуск последовательности (0→1): (АОсс => Стравливание) ИЛИ (НОсс => Стравливание) ИЛИ (Стравливание => Стравливание)
drm.transition.1 := am.Kr4.isOFF AND am.Kr1.isOFF AND am.Kr2.isOFF AND am.Kr6.isOFF; //1→2: Кран 4 закрыт И Кран 1 закрыт И Кран 2 закрыт И Кран 6 закрыт
drm.transition.2 := am.Kr5.isON AND aipar.Pg_inN.value < 0.2; //2→3: Кран 5 открыт И Р газа на входе К < 0.2 МПа
drm.transition.3 := TRUE; //3→0: Логическая 1
drm.transition.31 := break := NOT mde.NOss AND NOT mde.AOss AND NOT bleeding_full.drm.active; //Принудительный выход из последовательности (N→0): Отсутствие запускающих режимов

//Вызываем экземпляр интерфейсного функционального блока
drm(cycle := cycle);

CASE drm.step OF
-1:	//Сброс команд с предыдущих шагов
	finish := FALSE;
	//Условие запуска последовательности
	//(АОсс => Стравливание) ИЛИ (НОсс => Стравливание) ИЛИ (Стравливание => Стравливание)
	IF start AND NOT break THEN drm.step := 1; END_IF;
1:	//Запись уставки таймера шага
	drm.step := 1;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_Kr4_Off := drm.cmd.0 := TRUE; //Кран 4 закрыть
	(*1*) drm.error.0 := am.Kr4.notOff; //Кран 4 не закрылся

	(*2*) cmd_Kr1_Off := drm.cmd.1 := TRUE; //Кран 1 закрыть
	(*2*) drm.error.1 := am.Kr1.notOff; //Кран 1 не закрылся

	(*3*) cmd_Kr2_Off := drm.cmd.2 := TRUE; //Кран 2 закрыть
	(*3*) drm.error.2 := am.Kr2.notOff; //Кран 2 не закрылся

	(*4*) cmd_Kr6_Off := drm.cmd.3 := TRUE; //Кран 6 закрыть
	(*4*) drm.error.3 := am.Kr6.notOff; //Кран 6 не закрылся

	//Условие перехода (1)→(2)
	//Кран 4 закрыт И Кран 1 закрыт И Кран 2 закрыт И Кран 6 закрыт
	IF (am.Kr4.isOFF AND am.Kr1.isOFF AND am.Kr2.isOFF AND am.Kr6.isOFF) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2;
		cmd_Kr4_Off := FALSE; //Кран 4 закрыть
		cmd_Kr1_Off := FALSE; //Кран 1 закрыть
		cmd_Kr2_Off := FALSE; //Кран 2 закрыть
		cmd_Kr6_Off := FALSE; //Кран 6 закрыть
	END_IF;
2:	//Запись уставки таймера шага
	drm.step := 2;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_Kr5_On := drm.cmd.0 := TRUE; //Кран 5 открыть
	(*1*) drm.error.0 := am.Kr5.notOn; //Кран 5 не открылся

	(*2*) bleeding := drm.cmd.1 := TRUE; //Стравливание
	(*2*) drm.error.1 := aipar.Pg_inN.value > 0.2; //Р газа на входе К > 0.2 МПа

	//Условие перехода (2)→(3)
	//Кран 5 открыт И Р газа на входе К < 0.2 МПа
	IF (am.Kr5.isON AND aipar.Pg_inN.value < 0.2) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 3;
		cmd_Kr5_On := FALSE; //Кран 5 открыть
		bleeding := FALSE; //Стравливание
	END_IF;
3:	//Запись уставки таймера шага
	drm.step := 3;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) finish := drm.cmd.0 := TRUE; //Завершение

	//Условие перехода (3)→(0)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
		finish := FALSE; //Завершение
	END_IF;
END_CASE

//Принудительный выход из последовательности
IF break THEN
	drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE;
	cmd_Kr4_Off := FALSE; //Кран 4 закрыть
	cmd_Kr1_Off := FALSE; //Кран 1 закрыть
	cmd_Kr2_Off := FALSE; //Кран 2 закрыть
	cmd_Kr6_Off := FALSE; //Кран 6 закрыть
	cmd_Kr5_On := FALSE; //Кран 5 открыть
	bleeding := FALSE; //Стравливание
	finish := FALSE; //Завершение
END_IF;

//Собираем переходы для визуализации
drm.transition.0 := start := KPK.cmd_filling OR APK.cmd_filling; //Запуск последовательности (0→1): (КПК => Заполнение) ИЛИ (АПК => Заполнение)
drm.transition.1 := am.Kr4.isON; //1→2: Кран 4 открыт
drm.transition.2 := TRUE; //2→3: Логическая 1
drm.transition.3 := am.Kr5.isOFF; //3→4: Кран 5 закрыт
drm.transition.4 := alg.nIncPgN AND aipar.Pg_outN.value > 2.942; //4→5: Рост давления в контуре > 0.2 МПа в секунду И давление в контуре > 30 кгс/см2
drm.transition.5 := TRUE; //5→6: Логическая 1
drm.transition.6 := am.Kr1.isON; //6→7: Кран 1 открыт
drm.transition.7 := am.Kr4.isOFF; //7→8: Кран 4 закрыт
drm.transition.8 := TRUE; //8→0: Логическая 1
drm.transition.31 := break := alg.AO; //Принудительный выход из последовательности (N→0): Режимы аварийного останова

//Вызываем экземпляр интерфейсного функционального блока
drm(cycle := cycle);

