	IF (alg.nIncPgN AND aipar.Pg_outN.value > 2.942) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 5;
		filling := FALSE; //Заполнение
