	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_Kr4_Off := drm.cmd.0 := TRUE; //Кран 4 закрыть
	(*1*) drm.error.0 := am.Kr4.notOff; //Кран 4 не закрылся

	//Условие перехода (7)→(8)
