//Собираем переходы для визуализации drm.transition.0 := start := mde.AOss; //Запуск последовательности (0→1): Режим АОсс drm.transition.1 := am.Kr4.isOFF AND ( acpar.Nst.value < 100.0 OR acpar.Nst.flt ); //1→2: Кран 4 закрыт И Nст < 100 об/мин drm.transition.2 := bleeding.finish; //2→3: Подрежим "Стравливание контура компрессора" завершен drm.transition.3 := TRUE; //3→4: Логическая 1 drm.transition.4 := TRUE; //4→5: Логическая 1 drm.transition.5 := TRUE; //5→6: Логическая 1 drm.transition.6 := tch.Unlock.value; //6→0: Деблокировка drm.transition.31 := break := NOT mde.AOss; //Принудительный выход из последовательности (N→0): Снятие режима
