(*9*) cmd_KR12_Off := drm.cmd.8 := TRUE; //Закрытие крана 12, открытие крана 9 (*9*) drm.error.8 := am.KR12.notOff OR am.KR9.notOn; //Кран 12 не закрылся, кран 9 не открылся
