(*11*) am.KR15.on := FALSE; //Кран 15 закрыть (*11*) drm.error.10 := am.KR15.notOff; //Кран 15 не закрылся
(*12*) cmd_Kr4_Off := drm.cmd.11 := TRUE; //Кран 4 закрыть (*12*) drm.error.11 := am.Kr4.notOff; //Кран 4 не закрылся
