(*14*) check_Nst := drm.cmd.13 := TRUE; //Проверка Nст (*14*) drm.error.13 := acpar.Nst.value > 100.0; //Nст > 100 об/мин
//Условие перехода (1)→(2) //Кран 4 закрыт И Nст < 100 об/мин IF (am.Kr4.isOFF AND ( acpar.Nst.value < 100.0 OR acpar.Nst.flt )) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2; cmd_M_K := FALSE; //Запуск последовательности "Переход М-К" sh_ms_off := FALSE; //Снятие защиты по маслосистеме ТК и СТ cmd_KPV15_On := FALSE; //Открыть КПВ 1, 5 cmd_KPV234_On := FALSE; //Открыть КПВ 2, 3, 4 cmd_sh_TG_Off := FALSE; //Снятие защиты по ТГ cmd_PNU_S_On := FALSE; //Включение маслонасосов смазки и уплотнения cmd_KR12_Off := FALSE; //Закрытие крана 12, открытие крана 9 cmd_VS_Off := FALSE; //Останов воздушного стартера cmd_Kr4_Off := FALSE; //Кран 4 закрыть cmd_KR11_Off := FALSE; //Закрытие крана 11, открытие крана 10 check_Nst := FALSE; //Проверка Nст END_IF; 2: //Запись уставки таймера шага drm.step := 2;//Текущий шаг drm.timer_pt := cycle; //Таймер: один цикл вызова
