//Условие перехода (6)→(0) //Деблокировка IF (tch.Unlock.value) AND drm.timeout THEN drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1; finish := FALSE; //Завершение END_IF; END_CASE
//Принудительный выход из последовательности IF break THEN drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; emergStopCom := FALSE; //Аварийный останов двигателя cmd_M_K := FALSE; //Запуск последовательности "Переход М-К" sh_ms_off := FALSE; //Снятие защиты по маслосистеме ТК и СТ cmd_KPV15_On := FALSE; //Открыть КПВ 1, 5 cmd_KPV234_On := FALSE; //Открыть КПВ 2, 3, 4 cmd_VNA_On := FALSE; //Включение Э/М ВНА cmd_sh_TG_Off := FALSE; //Снятие защиты по ТГ cmd_PNU_S_On := FALSE; //Включение маслонасосов смазки и уплотнения cmd_KR12_Off := FALSE; //Закрытие крана 12, открытие крана 9 cmd_VS_Off := FALSE; //Останов воздушного стартера cmd_Kr4_Off := FALSE; //Кран 4 закрыть cmd_KR11_Off := FALSE; //Закрытие крана 11, открытие крана 10 check_Nst := FALSE; //Проверка Nст cmd_bleeding := FALSE; //Запуск последовательности "Стравливание контура компрессора" check_Ntk := FALSE; //Выбег двигателя cmd_shPmN_Off := FALSE; //Снятие защиты по маслосистеме нагнетателя cmd_sh_dPmg_Off := FALSE; //Снятие защиты по перепаду "масло-газ" cmd_PNU_S_Off := FALSE; //Пуск таймера отключения ПНС, ПНУ finish := FALSE; //Завершение END_IF;

