drm.transition.2 := aipar.dPmg.value > 0.5 AND NOT dipar.Pm_N_Pn.value; //2→3: dP масло-газ > 0.5 кгс/см2 и Pm > 1 кгс/см2
drm.transition.3 := Filling.finish; //3→4: Подсистема "Газовая обвязка" запущена
drm.transition.4 := FuelReg.fReg.started; //4→5: Двигатель перешел в режим "Работа"
drm.transition.5 := TRUE; //5→0: Логическая 1
drm.transition.31 := break := alg.AO; //Принудительный выход из последовательности (N→0): Режимы аварийного останова

//Вызываем экземпляр интерфейсного функционального блока
drm(cycle := cycle);

CASE drm.step OF
-1:	//Сброс команд с предыдущих шагов
	finish := FALSE;
	//Условие запуска последовательности
	//Режим АПК
	IF start AND NOT break THEN drm.step := 1; END_IF;
1:	//Запись уставки таймера шага
	drm.step := 1;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) cmd_sound_On := drm.cmd.0 := TRUE; //Предпусковая сигнализация

	//Условие перехода (1)→(2)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2;
		cmd_sound_On := FALSE; //Предпусковая сигнализация
	END_IF;
2:	//Запись уставки таймера шага
	drm.step := 2;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_PNU_S_On := drm.cmd.0 := TRUE; //Включение маслонасосов смазки и уплотнения

	//Условие перехода (2)→(3)
	//dP масло-газ > 0.5 кгс/см2 и Pm > 1 кгс/см2
	IF (aipar.dPmg.value > 0.5 AND NOT dipar.Pm_N_Pn.value) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 3;
		cmd_PNU_S_On := FALSE; //Включение маслонасосов смазки и уплотнения
	END_IF;
3:	//Запись уставки таймера шага
	drm.step := 3;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_shPmN_On := drm.cmd.0 := TRUE; //Взвод защиты по маслосистеме нагнетателя

	(*2*) cmd_sh_dPmg_On := drm.cmd.1 := TRUE; //Взвод защиты по перепаду "масло-газ"

	(*3*) cmd_filling := drm.cmd.2 := drm.step_time <= cycle; //Запуск последовательности "Заполнение контура компрессора"

	//Условие перехода (3)→(4)
	//Подсистема "Газовая обвязка" запущена
	IF (Filling.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 4;
		cmd_shPmN_On := FALSE; //Взвод защиты по маслосистеме нагнетателя
		cmd_sh_dPmg_On := FALSE; //Взвод защиты по перепаду "масло-газ"
		cmd_filling := FALSE; //Запуск последовательности "Заполнение контура компрессора"
	END_IF;
4:	//Запись уставки таймера шага
	drm.step := 4;//Текущий шаг
	drm.inc := TRUE; //Выставляем признак инкремента

	//Команды текущего шага
	(*1*) cmd_start_D := drm.cmd.0 := drm.step_time <= cycle; //Запуск последовательности "Пуск двигателя"

	//Условие перехода (4)→(5)
	//Двигатель перешел в режим "Работа"
	IF (FuelReg.fReg.started) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 5;
		cmd_start_D := FALSE; //Запуск последовательности "Пуск двигателя"
	END_IF;
5:	//Запись уставки таймера шага
	drm.step := 5;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) finish := drm.cmd.0 := TRUE; //Завершение

	//Условие перехода (5)→(0)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
		finish := FALSE; //Завершение
	END_IF;
END_CASE

//Принудительный выход из последовательности
IF break THEN
	drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE;
	cmd_sound_On := FALSE; //Предпусковая сигнализация
	cmd_PNU_S_On := FALSE; //Включение маслонасосов смазки и уплотнения
	cmd_shPmN_On := FALSE; //Взвод защиты по маслосистеме нагнетателя
	cmd_sh_dPmg_On := FALSE; //Взвод защиты по перепаду "масло-газ"
	cmd_filling := FALSE; //Запуск последовательности "Заполнение контура компрессора"
	cmd_start_D := FALSE; //Запуск последовательности "Пуск двигателя"
	finish := FALSE; //Завершение
END_IF;

//Собираем переходы для визуализации
drm.transition.0 := start := btn.Bleeding.out; //Запуск последовательности (0→1): Нажата кнопка "Стравливание"
drm.transition.1 := bleeding.finish; //1→2: Подрежим "Стравливание контура компрессора" завершен
drm.transition.2 := TRUE; //2→3: Логическая 1
drm.transition.3 := TRUE; //3→0: Логическая 1
drm.transition.31 := break := mde.AOss; //Принудительный выход из последовательности (N→0): Режим АОсс

//Вызываем экземпляр интерфейсного функционального блока
drm(cycle := cycle);

CASE drm.step OF
-1:	//Сброс команд с предыдущих шагов
	finish := FALSE;
	//Условие запуска последовательности
	//Нажата кнопка "Стравливание"
	IF start AND NOT break THEN drm.step := 1; END_IF;
1:	//Запись уставки таймера шага
	drm.step := 1;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_bleeding := drm.cmd.0 := drm.step_time <= cycle; //Запуск последовательности "Стравливание контура компрессора"

	//Условие перехода (1)→(2)
	//Подрежим "Стравливание контура компрессора" завершен
	IF (bleeding.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2;
		cmd_bleeding := FALSE; //Запуск последовательности "Стравливание контура компрессора"
	END_IF;
2:	//Запись уставки таймера шага
	drm.step := 2;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_sh_dPmg_Off := drm.cmd.0 := TRUE; //Снятие защиты по перепаду "масло-газ"

	(*2*) cmd_shPmN_Off := drm.cmd.1 := TRUE; //Снятие защиты по маслосистеме нагнетателя

	(*3*) cmd_PNU_S_Off := drm.cmd.2 := TRUE; //Пуск таймера отключения ПНС, ПНУ

	//Условие перехода (2)→(3)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 3;
		cmd_sh_dPmg_Off := FALSE; //Снятие защиты по перепаду "масло-газ"
		cmd_shPmN_Off := FALSE; //Снятие защиты по маслосистеме нагнетателя
		cmd_PNU_S_Off := FALSE; //Пуск таймера отключения ПНС, ПНУ
	END_IF;
3:	//Запись уставки таймера шага
	drm.step := 3;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) finish := drm.cmd.0 := TRUE; //Завершение

	//Условие перехода (3)→(0)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
		finish := FALSE; //Завершение
	END_IF;
END_CASE

//Принудительный выход из последовательности
IF break THEN
	drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE;
	cmd_bleeding := FALSE; //Запуск последовательности "Стравливание контура компрессора"
	cmd_sh_dPmg_Off := FALSE; //Снятие защиты по перепаду "масло-газ"
	cmd_shPmN_Off := FALSE; //Снятие защиты по маслосистеме нагнетателя
	cmd_PNU_S_Off := FALSE; //Пуск таймера отключения ПНС, ПНУ
	finish := FALSE; //Завершение
END_IF;

//Собираем переходы для визуализации
drm.transition.0 := start := check.btn OR btn.Check_SAU.out OR check.tmr12H.Q; //Запуск последовательности (0→1): Нажата одна из пусковых кнопок ИЛИ Кнопка "Контроль САУ" ИЛИ Каждые 12 часов
drm.transition.1 := crs.Vs_D_Av.signalization AND crs.BZA_alr.signalization AND crs.Vsst_HH.signalization AND crs.Vstk_HH.signalization; //1→2: Сформированы аварийные сигнализации двигателя
drm.transition.2 := TRUE; //2→0: Логическая 1
drm.transition.31 := break := btn.Cancel.out; //Принудительный выход из последовательности (N→0): Деблокировка

//Вызываем экземпляр интерфейсного функционального блока
drm(cycle := cycle);

CASE drm.step OF
-1:	//Сброс команд с предыдущих шагов
	finish := FALSE;
	//Условие запуска последовательности
	//Нажата одна из пусковых кнопок ИЛИ Кнопка "Контроль САУ" ИЛИ Каждые 12 часов
	IF start AND NOT break THEN drm.step := 1; END_IF;
1:	//Запись уставки таймера шага
	drm.step := 1;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) cmd_check_VibD := drm.cmd.0 := TRUE; //Контроль виброаппаратуры двигателя

	(*2*) cmd_check_BZA := drm.cmd.1 := TRUE; //Контроль БЗА двигателя

	(*3*) wait_crs := drm.cmd.2 := TRUE; //Ожидание аварийных сигнализаций

	//Условие перехода (1)→(2)
	//Сформированы аварийные сигнализации двигателя
	IF (crs.Vs_D_Av.signalization AND crs.BZA_alr.signalization AND crs.Vsst_HH.signalization AND crs.Vstk_HH.signalization) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2;
		cmd_check_VibD := FALSE; //Контроль виброаппаратуры двигателя
		cmd_check_BZA := FALSE; //Контроль БЗА двигателя
		wait_crs := FALSE; //Ожидание аварийных сигнализаций
	END_IF;
2:	//Запись уставки таймера шага
	drm.step := 2;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) finish := drm.cmd.0 := TRUE; //Завершение

	//Условие перехода (2)→(0)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
		finish := FALSE; //Завершение
	END_IF;
END_CASE

//Принудительный выход из последовательности
IF break THEN
	drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE;
	cmd_check_VibD := FALSE; //Контроль виброаппаратуры двигателя
	cmd_check_BZA := FALSE; //Контроль БЗА двигателя
	wait_crs := FALSE; //Ожидание аварийных сигнализаций
	finish := FALSE; //Завершение
END_IF;

//Собираем переходы для визуализации
drm.transition.0 := start := mde.HP; //Запуск последовательности (0→1): Режим ХП
drm.transition.1 := TRUE; //1→2: Логическая 1
drm.transition.2 := aipar.dPmg.value > 0.5 AND NOT dipar.Pm_N_Pn.value; //2→3: dP масло-газ > 0.5 кгс/см2 и Pm > 1 кгс/см2
drm.transition.3 := am.KR11.isOn AND am.KR10.isOff; //3→4: Кран 11 открылся, кран 10 закрылся
drm.transition.4 := acpar.Ntk.value < 100.0; //4→5: Nвд < 100 об/мин
drm.transition.5 := TRUE; //5→6: Логическая 1
drm.transition.6 := TRUE; //6→7: Логическая 1
drm.transition.7 := am.KR13.isOff; //7→8: Холодная прокрутка двигателя завершена
drm.transition.8 := acpar.Ntk.value < 100 AND tch.nGas_N.value; //8→9: Nтк < 100 И Нет газа в контуре
drm.transition.9 := acpar.Ntk.value < 100 AND tch.Gas_N.value; //8→11: Nтк < 100 И Есть газ в контуре
drm.transition.10 := TRUE; //9→10: Логическая 1
drm.transition.11 := TRUE; //10→11: Логическая 1
drm.transition.12 := TRUE; //11→0: Логическая 1
drm.transition.31 := break := NOT mde.HP; //Принудительный выход из последовательности (N→0): Снятие режима

//Вызываем экземпляр интерфейсного функционального блока
drm(cycle := cycle);

CASE drm.step OF
-1:	//Сброс команд с предыдущих шагов
	finish := FALSE;
	//Условие запуска последовательности
	//Режим ХП
	IF start AND NOT break THEN drm.step := 1; END_IF;
1:	//Запись уставки таймера шага
	drm.step := 1;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) cmd_sound_On := drm.cmd.0 := TRUE; //Предпусковая сигнализация

	//Условие перехода (1)→(2)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2;
		cmd_sound_On := FALSE; //Предпусковая сигнализация
	END_IF;
2:	//Запись уставки таймера шага
	drm.step := 2;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_PNU_S_On := drm.cmd.0 := TRUE; //Пуск маслонасосов смазки и уплотнения

	//Условие перехода (2)→(3)
	//dP масло-газ > 0.5 кгс/см2 и Pm > 1 кгс/см2
	IF (aipar.dPmg.value > 0.5 AND NOT dipar.Pm_N_Pn.value) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 3;
		cmd_PNU_S_On := FALSE; //Пуск маслонасосов смазки и уплотнения
	END_IF;
3:	//Запись уставки таймера шага
	drm.step := 3;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_shPmN_On := drm.cmd.0 := TRUE; //Взвод защиты по маслосистеме нагнетателя

	(*2*) cmd_sh_dPmg_On := drm.cmd.1 := TRUE; //Взвод защиты по перепаду "масло-газ"

	(*3*) cmd_KR11_On := drm.cmd.2 := TRUE; //Открытие крана 11, закрытие крана 10
	(*3*) drm.error.2 := am.KR11.notOn OR am.KR10.notOff; //Кран 11 не открылся, кран 10 не закрылся

	//Условие перехода (3)→(4)
	//Кран 11 открылся, кран 10 закрылся
	IF (am.KR11.isOn AND am.KR10.isOff) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 4;
		cmd_shPmN_On := FALSE; //Взвод защиты по маслосистеме нагнетателя
		cmd_sh_dPmg_On := FALSE; //Взвод защиты по перепаду "масло-газ"
		cmd_KR11_On := FALSE; //Открытие крана 11, закрытие крана 10
	END_IF;
4:	//Запись уставки таймера шага
	drm.step := 4;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) check := drm.cmd.0 := TRUE; //Проверка Nвд
	(*1*) drm.error.0 := acpar.Ntk.value > 100.0; //Nвд > 100 об/мин

	//Условие перехода (4)→(5)
	//Nвд < 100 об/мин
	IF (acpar.Ntk.value < 100.0) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 5;
		check := FALSE; //Проверка Nвд
	END_IF;
5:	//Запись уставки таймера шага
	drm.step := 5;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_VS_On := drm.cmd.0 := drm.step_time <= cycle; //Пуск воздушного стартера
	(*1*) drm.error.0 := am.KR13.notOn; //Кран 13 не открылся

	//Условие перехода (5)→(6)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 6;
		cmd_VS_On := FALSE; //Пуск воздушного стартера
	END_IF;
6:	//Запись уставки таймера шага
	drm.step := 6;//Текущий шаг
	drm.timer_pt := 120; //Таймер: 120 секунд

	//Команды текущего шага
	(*1*) cmd_sh_Pm_Starter := drm.cmd.0 := drm.step_time <= cycle; //Взвод защиты по давлению масла ВС

	(*2*) cmd_HP_D := drm.cmd.1 := drm.step_time <= cycle; //Холодная прокрутка двигателя

	//Условие перехода (6)→(7)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 7;
		cmd_sh_Pm_Starter := FALSE; //Взвод защиты по давлению масла ВС
		cmd_HP_D := FALSE; //Холодная прокрутка двигателя
	END_IF;
7:	//Запись уставки таймера шага
	drm.step := 7;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_VS_Off := drm.cmd.0 := TRUE; //Останов воздушного стартера
	(*1*) drm.error.0 := am.KR13.notOff; //Кран 13 не закрылся

	//Условие перехода (7)→(8)
	//Холодная прокрутка двигателя завершена
	IF (am.KR13.isOff) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 8;
		cmd_VS_Off := FALSE; //Останов воздушного стартера
	END_IF;
8:	//Запись уставки таймера шага
	drm.step := 8;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_KR11_Off := drm.cmd.0 := TRUE; //Закрытие крана 11, открытие крана 10
	(*1*) drm.error.0 := am.KR11.notOff OR am.KR10.notOn; //Кран 11 не закрылся, кран 10 не открылся

	(*2*) cmd_HP_stop_D := drm.cmd.1 := TRUE; //Выбег двигателя после ХП

	//Условие перехода на шаг (9)
	//Nтк < 100 И Нет газа в контуре
	IF (acpar.Ntk.value < 100 AND tch.nGas_N.value) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 9;
		cmd_KR11_Off := FALSE; //Закрытие крана 11, открытие крана 10
		cmd_HP_stop_D := FALSE; //Выбег двигателя после ХП
	END_IF;
	//Условие перехода (8)→(11)
	//Nтк < 100 И Есть газ в контуре
	IF (acpar.Ntk.value < 100 AND tch.Gas_N.value) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 11;
		cmd_KR11_Off := FALSE; //Закрытие крана 11, открытие крана 10
		cmd_HP_stop_D := FALSE; //Выбег двигателя после ХП
	END_IF;
9:	//Запись уставки таймера шага
	drm.step := 9;//Текущий шаг
	drm.timer_pt := 2; //Таймер: 2 секунд

	//Команды текущего шага
	(*1*) cmd_shPmN_Off := drm.cmd.0 := TRUE; //Снятие защиты по маслосистеме

	(*2*) cmd_PNU_Off := drm.cmd.1 := TRUE; //Отключение маслонасоса уплотнения
	(*2*) drm.error.1 := am.PNU.notOff; //Маслонасос уплотнений не выключился

	(*3*) cmd_sh_dPmg_Off := drm.cmd.2 := TRUE; //Снятие защиты по перепаду "масло-газ"

	//Условие перехода (9)→(10)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 10;
		cmd_shPmN_Off := FALSE; //Снятие защиты по маслосистеме
		cmd_PNU_Off := FALSE; //Отключение маслонасоса уплотнения
		cmd_sh_dPmg_Off := FALSE; //Снятие защиты по перепаду "масло-газ"
	END_IF;
10:	//Запись уставки таймера шага
	drm.step := 10;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_PNS_Off := drm.cmd.0 := TRUE; //Отключение маслонасоса смазки
	(*1*) drm.error.0 := am.PNS.notOff; //Маслонасос смазки не выключился

	//Условие перехода (10)→(11)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 11;
		cmd_PNS_Off := FALSE; //Отключение маслонасоса смазки
	END_IF;
11:	//Запись уставки таймера шага
	drm.step := 11;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) finish := drm.cmd.0 := drm.step_time <= cycle; //Завершение

	//Условие перехода (11)→(0)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
		finish := FALSE; //Завершение
	END_IF;
END_CASE

//Принудительный выход из последовательности
IF break THEN
	drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE;
	cmd_sound_On := FALSE; //Предпусковая сигнализация
	cmd_PNU_S_On := FALSE; //Пуск маслонасосов смазки и уплотнения
	cmd_shPmN_On := FALSE; //Взвод защиты по маслосистеме нагнетателя
	cmd_sh_dPmg_On := FALSE; //Взвод защиты по перепаду "масло-газ"
	cmd_KR11_On := FALSE; //Открытие крана 11, закрытие крана 10
	check := FALSE; //Проверка Nвд
	cmd_VS_On := FALSE; //Пуск воздушного стартера
	cmd_sh_Pm_Starter := FALSE; //Взвод защиты по давлению масла ВС
	cmd_HP_D := FALSE; //Холодная прокрутка двигателя
	cmd_VS_Off := FALSE; //Останов воздушного стартера
	cmd_KR11_Off := FALSE; //Закрытие крана 11, открытие крана 10
	cmd_HP_stop_D := FALSE; //Выбег двигателя после ХП
	cmd_shPmN_Off := FALSE; //Снятие защиты по маслосистеме
	cmd_PNU_Off := FALSE; //Отключение маслонасоса уплотнения
	cmd_sh_dPmg_Off := FALSE; //Снятие защиты по перепаду "масло-газ"
	cmd_PNS_Off := FALSE; //Отключение маслонасоса смазки
	finish := FALSE; //Завершение
END_IF;

//Собираем переходы для визуализации
drm.transition.0 := start := mde.KPK; //Запуск последовательности (0→1): Режим КПК
drm.transition.1 := TRUE; //1→2: Логическая 1
drm.transition.2 := aipar.dPmg.value > 0.5 AND NOT dipar.Pm_N_Pn.value; //2→3: dP масло-газ > 0.5 кгс/см2 и Pm > 1 кгс/см2
drm.transition.3 := subsystem.go.work; //3→4: Подсистема "Газовая обвязка" запущена
drm.transition.4 := am.KR12.isON AND am.KR9.isOff AND aipar.Ptg_inTRK.value > 1.96; //4→5: Кран 12 открылся И кран 9 закрылся И Pтг > 1.96
drm.transition.5 := am.KR12.isOFF AND am.KR9.isON; //5→6: Кран 12 закрылся И кран 9 открылся
drm.transition.6 := am.Kr6.isOFF; //6→7: Кран 6 закрыт
drm.transition.7 := am.Kr1.isOFF AND am.Kr2.isOFF AND am.Kr4.isON; //7→8: Кран 1 закрыт И Кран 2 закрыт И Кран 4 открыт
drm.transition.8 := TRUE; //8→0: Логическая 1
drm.transition.31 := break := NOT mde.KPK; //Принудительный выход из последовательности (N→0): Снятие режима

//Вызываем экземпляр интерфейсного функционального блока
drm(cycle := cycle);

CASE drm.step OF
-1:	//Сброс команд с предыдущих шагов
	finish := FALSE;
	//Условие запуска последовательности
	//Режим КПК
	IF start AND NOT break THEN drm.step := 1; END_IF;
1:	//Запись уставки таймера шага
	drm.step := 1;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) cmd_sound_On := drm.cmd.0 := TRUE; //Предпусковая сигнализация

	//Условие перехода (1)→(2)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2;
		cmd_sound_On := FALSE; //Предпусковая сигнализация
	END_IF;
2:	//Запись уставки таймера шага
	drm.step := 2;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_PNU_S_On := drm.cmd.0 := TRUE; //Пуск маслонасосов уплотнения и смазки
	(*1*) drm.error.0 := am.PNU.notOn; //Маслонасос уплотнений не включился

	//Условие перехода (2)→(3)
	//dP масло-газ > 0.5 кгс/см2 и Pm > 1 кгс/см2
	IF (aipar.dPmg.value > 0.5 AND NOT dipar.Pm_N_Pn.value) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 3;
		cmd_PNU_S_On := FALSE; //Пуск маслонасосов уплотнения и смазки
	END_IF;
3:	//Запись уставки таймера шага
	drm.step := 3;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_sh_dPmg_On := drm.cmd.0 := TRUE; //Взвод защиты по перепаду "масло-газ"

	(*2*) cmd_shPmN_On := drm.cmd.1 := TRUE; //Взвод защиты по маслосистеме нагнетателя

	(*3*) cmd_filling := drm.cmd.2 := drm.step_time <= cycle; //Запуск последовательности "Заполнение контура компрессора"

	//Условие перехода (3)→(4)
	//Подсистема "Газовая обвязка" запущена
	IF (subsystem.go.work) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 4;
		cmd_sh_dPmg_On := FALSE; //Взвод защиты по перепаду "масло-газ"
		cmd_shPmN_On := FALSE; //Взвод защиты по маслосистеме нагнетателя
		cmd_filling := FALSE; //Запуск последовательности "Заполнение контура компрессора"
	END_IF;
4:	//Запись уставки таймера шага
	drm.step := 4;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_KR12_On := drm.cmd.0 := TRUE; //Открытие крана 12, закрытие крана 9
	(*1*) drm.error.0 := am.KR12.notOn OR am.KR9.notOff; //Кран 12 не открылся, кран 9 не закрылся

	//Условие перехода (4)→(5)
	//Кран 12 открылся И кран 9 закрылся И Pтг > 1.96
	IF (am.KR12.isON AND am.KR9.isOff AND aipar.Ptg_inTRK.value > 1.96) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 5;
		cmd_KR12_On := FALSE; //Открытие крана 12, закрытие крана 9
	END_IF;
5:	//Запись уставки таймера шага
	drm.step := 5;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_KR12_Off := drm.cmd.0 := TRUE; //Закрытие крана 12, открытие крана 9
	(*1*) drm.error.0 := am.KR12.notOff OR am.KR9.notOn; //Кран 12 не закрылся, кран 9 не открылся

	//Условие перехода (5)→(6)
	//Кран 12 закрылся И кран 9 открылся
	IF (am.KR12.isOFF AND am.KR9.isON) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 6;
		cmd_KR12_Off := FALSE; //Закрытие крана 12, открытие крана 9
	END_IF;
6:	//Запись уставки таймера шага
	drm.step := 6;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_Kr6_Off := drm.cmd.0 := TRUE; //Кран 6 закрыть
	(*1*) drm.error.0 := am.Kr6.notOff; //Кран 6 не закрылся

	//Условие перехода (6)→(7)
	//Кран 6 закрыт
	IF (am.Kr6.isOFF) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 7;
		cmd_Kr6_Off := FALSE; //Кран 6 закрыть
	END_IF;
7:	//Запись уставки таймера шага
	drm.step := 7;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_Kr1_Off := drm.cmd.0 := TRUE; //Кран 1 закрыть
	(*1*) drm.error.0 := am.Kr1.notOff; //Кран 1 не закрылся

	(*2*) cmd_Kr2_Off := drm.cmd.1 := TRUE; //Кран 2 закрыть
	(*2*) drm.error.1 := am.Kr2.notOff; //Кран 2 не закрылся

	(*3*) cmd_Kr4_On := drm.cmd.2 := TRUE; //Кран 4 открыть
	(*3*) drm.error.2 := am.Kr4.notOn; //Кран 4 не открылся

	//Условие перехода (7)→(8)
	//Кран 1 закрыт И Кран 2 закрыт И Кран 4 открыт
	IF (am.Kr1.isOFF AND am.Kr2.isOFF AND am.Kr4.isON) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 8;
		cmd_Kr1_Off := FALSE; //Кран 1 закрыть
		cmd_Kr2_Off := FALSE; //Кран 2 закрыть
		cmd_Kr4_On := FALSE; //Кран 4 открыть
	END_IF;
8:	//Запись уставки таймера шага
	drm.step := 8;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) finish := drm.cmd.0 := TRUE; //Завершение

	//Условие перехода (8)→(0)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
		finish := FALSE; //Завершение
	END_IF;
END_CASE

//Принудительный выход из последовательности
IF break THEN
	drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE;
	cmd_sound_On := FALSE; //Предпусковая сигнализация
	cmd_PNU_S_On := FALSE; //Пуск маслонасосов уплотнения и смазки
	cmd_sh_dPmg_On := FALSE; //Взвод защиты по перепаду "масло-газ"
	cmd_shPmN_On := FALSE; //Взвод защиты по маслосистеме нагнетателя
	cmd_filling := FALSE; //Запуск последовательности "Заполнение контура компрессора"
	cmd_KR12_On := FALSE; //Открытие крана 12, закрытие крана 9
	cmd_KR12_Off := FALSE; //Закрытие крана 12, открытие крана 9
	cmd_Kr6_Off := FALSE; //Кран 6 закрыть
	cmd_Kr1_Off := FALSE; //Кран 1 закрыть
	cmd_Kr2_Off := FALSE; //Кран 2 закрыть
	cmd_Kr4_On := FALSE; //Кран 4 открыть
	finish := FALSE; //Завершение
END_IF;

//Собираем переходы для визуализации
drm.transition.0 := start := mde.K_M; //Запуск последовательности (0→1): (Режим Переход К-М)
drm.transition.1 := am.Kr2.isON; //1→2: Кран 2 открыт
drm.transition.2 := am.Kr6.isOff; //2→3: Кран 6 закрыт
drm.transition.3 := TRUE; //3→0: Логическая 1
drm.transition.31 := break := alg.AO OR mde.M_K; //Принудительный выход из последовательности (N→0): Режимы аварийного останова ИЛИ Режим "Переход М-К"

