drm.transition.3 := TRUE; //3→0: Логическая 1
drm.transition.31 := break := mde.AOss OR mde.AObs OR mde.K_M; //Принудительный выход из последовательности (N→0): Режим АОсс ИЛИ Режим АОбс ИЛИ Режим "Переход К-М"

