drm.transition.1 := M_K.finish; //1→2: Последовательность "Переход М-К" завершена
drm.transition.2 := FuelReg.fReg.cooling; //2→3: Двигатель перешел на малый газ для охлаждения
drm.transition.3 := NOT FuelReg.fReg.cooling; //3→4: Охлаждение двигателя завершено
