	drm.step := 8;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_VNA_On := FALSE; //Отключение Э/М ВНА

	(*2*) finish := drm.cmd.1 := drm.step_time <= cycle; //Завершение

	//Условие перехода (8)→(0)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
