	(*2*) drm.error.1 := NOT FuelReg.fReg.cooling; //Д не перешел на малый газ для охлаждения

	//Условие перехода (2)→(3)
	//Двигатель перешел на малый газ для охлаждения
	IF (FuelReg.fReg.cooling) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 3;
		sh_ms_off := FALSE; //Снятие защиты по маслосистеме ТК и СТ
	END_IF;
3:	//Запись уставки таймера шага
	drm.step := 3;//Текущий шаг
	drm.inc := TRUE; //Выставляем признак инкремента

	//Команды текущего шага
	(*1*) cooling := drm.cmd.0 := TRUE; //Охлаждение двигателя

	//Условие перехода (3)→(4)
	//Охлаждение двигателя завершено
	IF (NOT FuelReg.fReg.cooling) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 4;
		cooling := FALSE; //Охлаждение двигателя
	END_IF;
4:	//Запись уставки таймера шага
	drm.step := 4;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) alg.normalStopCom := FALSE; //Нормальный останов двигателя

	(*2*) cmd_PNU_S_On := drm.cmd.1 := TRUE; //Включение маслонасосов смазки и уплотнения

	(*3*) cmd_VNA_On := drm.cmd.2 := TRUE; //Включение Э/М ВНА

	(*4*) cmd_KPV234_On := drm.cmd.3 := TRUE; //Открыть КПВ 2, 3, 4
	(*4*) drm.error.3 := am.KPV2.notOn OR am.KPV3.notOn OR am.KPV4.notOn; //КПВ 2, 3, 4 не открылись

	(*5*) cmd_KR12_Off := drm.cmd.4 := TRUE; //Закрытие крана 12, открытие крана 9
	(*5*) drm.error.4 := am.KR12.notOff OR am.KR9.notOn; //Кран 12 не закрылся, кран 9 не открылся

	(*6*) cmd_sh_TG_Off := drm.cmd.5 := TRUE; //Снятие защиты по ТГ

	(*7*) cmd_SK_Off := drm.cmd.6 := TRUE; //СК закрыть

	//Условие перехода (4)→(5)
	//Подача топливного газа прекращена
	IF (am.KR9.ison AND am.KR12.isOff) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 5;
		cmd_PNU_S_On := FALSE; //Включение маслонасосов смазки и уплотнения
		cmd_KPV234_On := FALSE; //Открыть КПВ 2, 3, 4
		cmd_KR12_Off := FALSE; //Закрытие крана 12, открытие крана 9
		cmd_sh_TG_Off := FALSE; //Снятие защиты по ТГ
		cmd_SK_Off := FALSE; //СК закрыть
	END_IF;
5:	//Запись уставки таймера шага
	drm.step := 5;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) check_Nst := drm.cmd.0 := TRUE; //Выбег нагнетателя

	//Условие перехода (5)→(6)
	//Nст < 100 об/мин
	IF (acpar.Nst.value < 100.0) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 6;
		check_Nst := FALSE; //Выбег нагнетателя
	END_IF;
6:	//Запись уставки таймера шага
	drm.step := 6;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_bleeding := drm.cmd.0 := drm.step_time <= cycle; //Запуск последовательности "Стравливание контура компрессора"

	//Условие перехода (6)→(7)
	//Подрежим "Стравливание контура компрессора" завершен
	IF (bleeding.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 7;
		cmd_bleeding := FALSE; //Запуск последовательности "Стравливание контура компрессора"
	END_IF;
7:	//Запись уставки таймера шага
	drm.step := 7;//Текущий шаг
	drm.timer_pt := 2; //Таймер: 2 секунд

	//Команды текущего шага
	(*1*) cmd_sh_dPmg_Off := drm.cmd.0 := TRUE; //Снятие защиты по перепаду "масло-газ"

	(*2*) cmd_PNU_S_Off := drm.cmd.1 := drm.step_time <= cycle; //Пуск таймера отключения ПНС, ПНУ

	(*3*) check_Ntk := drm.cmd.2 := TRUE; //Выбег двигателя

	//Условие перехода (7)→(8)
	//Nтк < 100 об/мин
	IF (acpar.Ntk.value < 100.0) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 8;
		cmd_sh_dPmg_Off := FALSE; //Снятие защиты по перепаду "масло-газ"
		cmd_PNU_S_Off := FALSE; //Пуск таймера отключения ПНС, ПНУ
		check_Ntk := FALSE; //Выбег двигателя
	END_IF;
8:	//Запись уставки таймера шага
	drm.step := 8;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_VNA_On := FALSE; //Отключение Э/М ВНА

	(*2*) cmd_shPmN_Off := drm.cmd.1 := TRUE; //Снятие защиты по маслосистеме нагнетателя

	(*3*) cmd_PNU_S_Off := drm.cmd.2 := drm.step_time <= cycle; //Пуск таймера отключения ПНС, ПНУ

	(*4*) finish := drm.cmd.3 := TRUE; //Завершение

	//Условие перехода (8)→(0)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
		cmd_shPmN_Off := FALSE; //Снятие защиты по маслосистеме нагнетателя
		cmd_PNU_S_Off := FALSE; //Пуск таймера отключения ПНС, ПНУ
		finish := FALSE; //Завершение
	END_IF;
END_CASE

//Принудительный выход из последовательности
IF break THEN
	drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE;
	cmd_M_K := FALSE; //Запуск последовательности "Переход М-К"
	sh_ms_off := FALSE; //Снятие защиты по маслосистеме ТК и СТ
	alg.normalStopCom := FALSE; //Нормальный останов двигателя
	cooling := FALSE; //Охлаждение двигателя
	cmd_PNU_S_On := FALSE; //Включение маслонасосов смазки и уплотнения
	cmd_VNA_On := FALSE; //Включение Э/М ВНА
	cmd_KPV234_On := FALSE; //Открыть КПВ 2, 3, 4
	cmd_KR12_Off := FALSE; //Закрытие крана 12, открытие крана 9
	cmd_sh_TG_Off := FALSE; //Снятие защиты по ТГ
	cmd_SK_Off := FALSE; //СК закрыть
	check_Nst := FALSE; //Выбег нагнетателя
	cmd_bleeding := FALSE; //Запуск последовательности "Стравливание контура компрессора"
	cmd_sh_dPmg_Off := FALSE; //Снятие защиты по перепаду "масло-газ"
	cmd_PNU_S_Off := FALSE; //Пуск таймера отключения ПНС, ПНУ
	check_Ntk := FALSE; //Выбег двигателя
	cmd_shPmN_Off := FALSE; //Снятие защиты по маслосистеме нагнетателя
	cmd_PNU_S_Off := FALSE; //Пуск таймера отключения ПНС, ПНУ
	finish := FALSE; //Завершение
END_IF;

//Деблокировка
unlock := tch.Unlock.value := btn.Unlock.out;

//Проверка защит
tch.CheckAlarm_on.value := btn.CheckAlarm_on.out OR tch.CheckAlarm_on.value AND NOT btn.CheckAlarm_off.out;
crs.common.CheckAlarm := alr.common.CheckAlarm := tch.CheckAlarm_on.value; 

// Подготовка данных для обработчиков сигнализаций	 
// Включение защиты по маслосистеме воздушного стартера
tmr.crsPmStarter_20.in 	:= am.Kr13.on;
alg.sh_Starter 			:= tmr.crsPmStarter_20.q;

// Защита по топливному газу
alg.sh_TG	:= ( Start_D.cmd_sh_TG_On OR alg.sh_TG ) AND NOT ( NOss.cmd_sh_TG_Off OR NObs.cmd_sh_TG_Off OR AOss.cmd_sh_TG_Off OR AObs.cmd_sh_TG_Off ) OR tch.GTDwork.value;

// Включение защиты по не розжигу (10 sec)
//tmr.crsNIgnition_10.IN	:= Start_D.cmd_sh_nIgnition AND NOT FuelReg.fReg.isFire;
alg.sh_nIgnition 		:= Start_D.cmd_sh_nIgnition AND NOT FuelReg.fReg.isFire; //tmr.crsNIgnition_10.Q;

// Включение защиты по не раскрутке (10 sec)
//tmr.crsNBoost_10.IN		:= ( Start_D.cmd_sh_nBoost OR tmr.crsNBoost_10.IN ) AND acpar.Ntk.value < 5600 AND am.SK.on;
alg.sh_nBoost			:= ( Start_D.cmd_sh_nBoost ) AND acpar.Ntk.value < 5600 AND am.SK.on; //tmr.crsNBoost_10.Q;

// Взвод защиты КПВ234 не закрыты
tmr.KPV234_wOpen.IN		:= ( Start_D.cmd_KPV234_Off OR tmr.KPV234_wOpen.IN ) AND NOT tmr.KPV234_wOpen.Q;
alg.KPV234_wOpen		:= ( tmr.KPV234_wOpen.Q OR alg.KPV234_wOpen ) AND NOT ( NOss.cmd_KPV234_On OR NObs.cmd_KPV234_On OR AOss.cmd_KPV234_On OR AObs.cmd_KPV234_On ) OR tch.GTDwork.value;

// Взвод защиты КПВ15 не закрыты
tmr.KPV15_wOpen.IN		:= ( acpar.NtkPrived.value > Ntk_KPV15Close OR tmr.KPV15_wOpen.IN ) AND NOT ( AOss.cmd_KPV15_On OR AObs.cmd_KPV15_On OR alg.normalStopCom );
alg.KPV15_wOpen			:= tmr.KPV15_wOpen.Q;

// Взвод защиты КПВ15 не открыты
tmr.KPV15_nOpen.IN		:= ( acpar.NtkPrived.value < Ntk_KPV15Open ) AND ( acpar.NtkPrived.value > Ntk_KPVClose );
alg.KPV15_nOpen			:= tmr.KPV15_nOpen.Q;

// Взвод защиты по давлению газа перед краном 13
alg.sh_Pg_inKR13		:= ( HP.cmd_VS_On OR Start_D.cmd_VS_On OR alg.sh_Pg_inKR13 ) AND NOT ( HP.cmd_VS_Off OR Start_D.cmd_VS_Off );

// Взвод защиты по давлению масла нагнетателя
alg.sh_PmN				:= ( KPK.cmd_shPmN_On OR HP.cmd_shPmN_On OR APK.cmd_shPmN_On OR alg.sh_PmN ) AND NOT ( HP.cmd_shPmN_Off OR NOss.cmd_shPmN_Off OR AOss.cmd_shPmN_Off OR Bleeding_full.cmd_shPmN_Off ) OR tch.GTDwork.value;

// Взвод защиты по давлению масла ТК и СТ
alg.sh_PmGTD			:= alg.KPV15_wOpen;

// Взвод защиты по давлению масла перед ДГ (САР)
alg.sh_SAR				:= alg.KPV234_wOpen;

// Взвод защиты по перепаду масло-газ
alg.sh_dPmg				:= ( KPK.cmd_sh_dPmg_On OR HP.cmd_sh_dPmg_On OR APK.cmd_sh_dPmg_On OR alg.sh_dPmg ) AND NOT ( HP.cmd_sh_dPmg_Off OR NOss.cmd_sh_dPmg_Off OR AOss.cmd_sh_dPmg_Off OR Bleeding_full.cmd_sh_dPmg_Off ) OR tch.Gas_N.value;

// Аварийный останов
alg.emergStopCom		:= AOss.emergStopCom OR AObs.emergStopCom;

// Вызов обработчиков сигнализаций
PPU_update(); // Предпусковые условия
ALR_update(); // Предупреждения
CRS_update(); // Аварии

