///Chekmarev
FUNCTION D_imit : BOOL
VAR
	Tm		: REAL; //  
	///start		: BOOL;
	PmGood	: BOOL;
END_VAR
VAR CONSTANT
	/// максимальные обороты ТК на стартере
	Nstart_max: REAL := 2050;
	/// номинальные обороты ТК
	Ntk_norm: REAL := 8300;
	// нагрев масла нагревателем
	Ten		: REAL := 65;
	/// нагрев масла двигателем
	dTm_max: REAL := 26;
	tau_m: REAL := (300 * cycle_time_base);
	tau_mb: REAL := (5000 * cycle_time_base);
END_VAR

///Chekmarev
FUNCTION D_imit : BOOL
VAR
	Tm		: REAL; //  
	///start		: BOOL;
	PmGood	: BOOL;
END_VAR
VAR CONSTANT
	/// максимальные обороты ТК на стартере
	Nstart_max: REAL := 2050;
	/// номинальные обороты ТК
	Ntk_norm: REAL := 8300;
	// нагрев масла нагревателем
	Ten		: REAL := 65;
	/// нагрев масла двигателем
	dTm_max: REAL := 26;
	tau_m: REAL := (300 * cycle_time_base);
	tau_mb: REAL := (5000 * cycle_time_base);
END_VAR

ST.xhtml:
//start := am.Kr11.isON AND am.Kr10.isOFF AND am.Kr13.on;

// Раскрутка стартером
//IF am.SK.isOFF AND start THEN
//	aipar.Ntk_1.sim_value := aipar.Ntk_1.value + ( Nstart_max - aipar.Ntk_1.value ) / tau_start;
//END_IF

// Выбег двигателя
//IF am.SK.isOFF AND NOT start THEN
//	aipar.Ntk_1.sim_value := aipar.Ntk_1.value - aipar.Ntk_1.value / tau_stop;
//END_IF

//aipar.Ntk_2.sim_value := aipar.Ntk_1.value + ( 10 * BOOL_TO_BYTE (aipar.Ntk_1.value > 10.0 ));

// Температура масла
Tm	:= aipar.Tm_outAVOM.value;
aipar.Tm_MB.sim_value	:= aipar.Tm_MB.value + ( Tm - aipar.Tm_MB.value) / tau_mb;	// в маслобаке
aipar.Tm_outD.sim_value	:= aipar.Tm_outD.sim_value + (aipar.Tm_inD.value + dTm_max * ( acpar.Ntk.value / Ntk_norm) - aipar.Tm_outD.sim_value) / tau_m;
aipar.Tm_inD.sim_value	:= aipar.Tm_MB.value - 0.5;		// на входе в двигатель
Tm	:= aipar.Tm_outAVOM.value;
aipar.Tm_MBU.sim_value	:= aipar.Tm_MBU.value + ( Tm - aipar.Tm_MBU.value ) / ( tau_mb * 5 ); // маслобак уплотнений

// q = 160 кг в мин // расход
// Q = 8380000 дж в мин // передача теплоты в масло
// ~ 2000 дж/(кгС) // теплоемкость масла
// Итог:
// dt = ~26 градусов за мин

PmGood	:= acpar.Ntk.value > 5000;

dipar.Pm_N_An.sim_value	:= NOT ( am.PNS.isOn OR PmGood );
dipar.Pm_N_Pn.sim_value := NOT ( am.PNS.isOn OR acpar.Ntk.value > 6880 );
dipar.Pm_TK_An.sim_value := acpar.Ntk.value < 7700;
dipar.Pm_ST_An.sim_value := dipar.Pm_TK_An.value;

// БЗА Готовность 2
dipar.BZA_ready_2.sim_value	:= PmGood;

// Положение концевиков КПВ
dipar.KPV1_ON.sim_value	:= acpar.Ntk.value > Ntk_KPVClose AND acpar.Ntk.value < 7710;
dipar.KPV1_off.sim_value	:= NOT ( acpar.Ntk.value > Ntk_KPVClose AND acpar.Ntk.value < 7500 );

dipar.KPV2_ON.sim_value	:= am.KPV2.ON AND PmGood;
dipar.KPV2_off.sim_value	:= NOT dipar.KPV2_ON.value;

dipar.KPV3_ON.sim_value	:= am.KPV3.ON AND PmGood;
dipar.KPV3_off.sim_value	:= NOT dipar.KPV3_ON.value;

dipar.KPV4_ON.sim_value	:= am.KPV4.ON AND PmGood;
dipar.KPV4_off.sim_value	:= NOT dipar.KPV4_ON.value;

dipar.KPV5_ON.sim_value	:= dipar.KPV1_ON.value;
dipar.KPV5_off.sim_value	:= dipar.KPV1_off.value;

