///
/// Назначение: 		Инициализация переменных
/// Автор: 			
/// Версия: 			00.00.01
FUNCTION fun_init : BOOL

ST.xhtml:
// Кран 1
am.Kr1.on 	:= Filling.cmd_Kr1_ON;
am.Kr1.off 	:= KPK.cmd_Kr1_Off OR NObs.cmd_Kr1_Off OR AObs.cmd_Kr1_Off OR Bleeding.cmd_Kr1_Off;
// Кран 1 смазка
dopar.Kr1m_ON.value	:= am.Kr1.offOut OR am.Kr1.onOut;

// Кран 2
//aspar.dP_Kr2.value := ABS(aipar.Pg_outN.value - aipar.Pg_aftKr2.value);
am.Kr2.on 	:= K_M.cmd_Kr2_ON;
am.Kr2.off	:= KPK.cmd_Kr2_Off OR M_K.cmd_Kr2_Off OR AObs.cmd_Kr2_Off OR Bleeding.cmd_Kr2_Off;
// Кран 2 смазка
dopar.Kr2m_ON.value	:= am.Kr2.offOut OR am.Kr2.onOut;

// Кран 4
am.Kr4.on 	:= Filling.cmd_Kr4_ON OR KPK.cmd_Kr4_ON OR NObs.cmd_Kr4_ON OR AObs.cmd_Kr4_ON;
am.Kr4.off 	:= Filling.cmd_Kr4_Off OR Bleeding.cmd_Kr4_Off OR AOss.cmd_Kr4_Off OR AObs.cmd_Kr4_Off;
// Кран 4 смазка
//dopar.Kr4m_ON.value	:= am.Kr4.offOut OR am.Kr4.onOut;

// Кран 5
am.Kr5.on 	:= Bleeding.cmd_Kr5_ON AND am.Kr6.isOFF;
am.Kr5.off 	:= Filling.cmd_Kr5_Off;
// Кран 5 смазка
//dopar.Kr5m_ON.value	:= am.Kr5.offOut OR am.Kr5.onOut;

// Кран 6
am.Kr6.on 	:= M_K.cmd_KR6_ON OR Filling.cmd_Kr6_ON OR s_tunpar.ASprot.emergOpenBypass;
am.Kr6.off 	:= K_M.cmd_Kr6_Off OR NObs.cmd_Kr6_Off OR Bleeding.cmd_Kr6_Off OR AObs.cmd_Kr6_Off OR KPK.cmd_Kr6_Off OR ( alg.KR6_off_after_emergOpenBypass.Qr AND mde.M );
// Кран 6 смазка
dopar.Kr6m_ON.value	:= am.Kr6.offOut OR am.Kr6.onOut;

subsystem.GO(
	goWork := filling.start, 
	goStop := bleeding.start, 
	work := filling.finish, 
	stop := bleeding.finish);
//Автоформируемый вызов последовательностей
go_update(cycle := cycle_time_base);

//Исполнительные механизмы
ALG_GO_AM();

//Нет газа в контуре Компрессора
tch.nGas_N.value := aipar.Pg_inN.value < 0.05 AND aipar.Pg_outN.value < 0.05 AND dipar.Kr5_ON.value AND NOT dipar.Kr5_off.value;
//Газ в контуре Компрессора
tch.Gas_N.value := (aipar.Pg_inN.value > 0.2 OR aipar.Pg_outN.value > 0.2) AND dipar.Kr5_off.value AND NOT dipar.Kr5_ON.value OR aipar.Pg_inN.value > 0.2 AND aipar.Pg_outN.value > 0.2;

//Нет роста Рг на вх. К на 0,05 МПа в течении 10 сек
IF aipar.Pg_inN.value - Pg_inN_old < 0.05 THEN
	bn.delay_filling := bn.delay_filling + cycle_time_base;
	IF bn.delay_filling > 10.0 THEN bn.delay_filling := 0.0; alg.nIncPgN := TRUE; END_IF;
ELSE
	alg.nIncPgN := FALSE;
END_IF;
Pg_inN_old := aipar.Pg_inN.value;

// выделение заднего фронта (снятия) предпомпажной защиты
alg.KR6_off_after_emergOpenBypass.in := s_tunpar.ASprot.emergOpenBypass;

IF imitGPA.imit_on THEN GO_imit(); END_IF;

