///
/// Назначение: 		Управление крановой обвязкой
/// Автор: 			
/// Версия: 			00.00.01
FUNCTION ALG_GO_link : BOOL

///Chekmarev
FUNCTION GO_imit : BOOL
VAR
	tau: REAL;
	p_in: REAL;
	kx: REAL;
END_VAR
VAR CONSTANT
	/// 30.6 кгс
	Pg_in: REAL := 3;
	Pg_out_max: REAL := 7;
	Nst_max: REAL := 8400;
END_VAR

///Chekmarev
FUNCTION GO_imit : BOOL
VAR
	tau: REAL;
	p_in: REAL;
	kx: REAL;
END_VAR
VAR CONSTANT
	/// 30.6 кгс
	Pg_in: REAL := 3;
	Pg_out_max: REAL := 7;
	Nst_max: REAL := 8400;
END_VAR

ST.xhtml:
kx := (Pg_out_max - Pg_in) / Nst_max * BOOL_TO_INT( am.Kr6.isOFF );

//Давление газа в Н
IF NOT dipar.Kr5_off.value THEN 
	tau := 20.0; 
ELSIF dipar.Kr4_ON.value THEN 
	tau := 50.0; 
ELSIF (dipar.Kr1_ON.value OR dipar.Kr2_ON.value) THEN 
	tau := 10.0;  ELSE tau := 100.0; 
END_IF;

IF NOT dipar.Kr5_off.value THEN p_in := 0.0;
ELSIF dipar.Kr6_ON.value AND am.Kr6.isOFF THEN p_in := Pg_in;
ELSIF dipar.Kr4_ON.value OR dipar.Kr1_ON.value THEN p_in := Pg_in;
END_IF;

IF tau < 100.0 THEN 
	aipar.Pg_inN.sim_value := aipar.Pg_inN.sim_value + (p_in - aipar.Pg_inN.value) / (tau);
	aipar.Pg_outN.sim_value := aipar.Pg_inN.sim_value + acpar.Nst.value * kx;
END_IF; 

dipar.Pg_outKR1.sim_value := aipar.Pg_inN.value > 2.6;

//dipar.SK_OF.sim_value	:= am.SK.isOFF;
//dipar.SK_ON.sim_value	:= am.SK.isON;

//Т газа
aipar.Tg_inN.sim_value := aipar.Tg_inN.sim_value + (aipar.Ta_inK.value + aipar.Pg_inN.value * 4.2 - aipar.Tg_inN.sim_value)/(tau_det);
aipar.Tg_outN.sim_value := aipar.Tg_outN.sim_value + (aipar.Ta_inK.value + aipar.Pg_outN.value * 4.2 - aipar.Tg_outN.sim_value)/(tau_det);

IF aipar.Pg_inN.value < 0 THEN aipar.Pg_inN.sim_value := 0; END_IF;
IF aipar.Pg_outN.value < 0 THEN aipar.Pg_outN.sim_value := 0; END_IF;

