///
/// Назначение: 		Вызов подрежимов
/// Автор: 			
/// Версия: 			00.00.01
FUNCTION ALG_SMD_link : BOOL

///
/// Назначение: 		Формирование выходных сигналов, не входящих ни в одну группу
/// Автор: 			
/// Версия: 			00.00.01
FUNCTION ALG_AM : BOOL

ST.xhtml:
//am.KPV1.on	:= ( AOss.cmd_KPV15_ON OR AObs.cmd_KPV15_ON OR am.KPV1.on ) AND NOT alg.V_000;
//am.KPV5.on	:= am.KPV1.on;

// Заглушка, т.к. КПВ1,5 управляются АУП-10
KPVOpen	:= ( acpar.NtkPrived.value > Ntk_KPVClose AND acpar.NtkPrived.value < Ntk_KPV15Open );
// КПВ 1
am.KPV1.on	:= KPVOpen;
// КПВ 2
am.KPV2.on	:= ( Start_D.cmd_KPV_On OR NOss.cmd_KPV234_ON OR NObs.cmd_KPV234_ON OR AOss.cmd_KPV234_ON OR AObs.cmd_KPV234_ON OR am.KPV2.on OR alg.V_000 ) AND NOT Start_D.cmd_KPV234_Off;
// КПВ 3
am.KPV3.on	:= am.KPV2.on;
// КПВ 4
am.KPV4.on	:= am.KPV2.on;
// КПВ 5
am.KPV5.on	:= KPVOpen;

// ВНА
am.VNA.on	:= Start_D.cmd_VNA_On OR NObs.cmd_VNA_On OR NOss.cmd_VNA_On OR AObs.cmd_VNA_On OR AOss.cmd_VNA_On;
// Обогрев ВНА
engine.VNAheat( par_value := aipar.Ta_inK.value, par_brk := aipar.Ta_inK.flt );
am.VNA_heat.on	:= ( engine.VNAheat.out OR dipar.Ace_alr.value ) AND NOT mde.Repair ;

// Агрегат зажигания
engine.AZ_off(IN := Start_D.cmd_AZ_ON);
am.AZ.on	:= engine.AZ_off.Q;

// Стопорный клапан
//alg.SK_tr	:= (Start_D.cmd_SK_On OR alg.SK_tr) AND NOT (alg.AO OR alg.NO);
//am.SK.on	:= alg.SK_tr;

am.SK.on	:= (Start_D.cmd_SK_On OR am.SK.on) AND NOT (alg.AO OR NOss.cmd_SK_Off OR NObs.cmd_SK_Off);

tmr.crsPmStarter_20();
//tmr.crsNIgnition_10();
//tmr.crsNBoost_10();
tmr.KPV15_nOpen();
tmr.KPV15_wOpen();
tmr.KPV234_wOpen();
tmr.PNU_S_Off();
tmr.PNU_S_pumpH();

//Стопорный клапан
//Тип: 1x2
am.SK(
	DU_prm := alg.V_000,
	onSigFlt := dipar.SK_ON.flt,
	onSig := dipar.SK_ON.value,
	onSig_sim_on := dipar.SK_ON.sim_on,
	onSig_sim_value := dipar.SK_ON.sim_value,
	offSigFlt	:= dipar.SK_off.flt,
	offSig		:= dipar.SK_off.value,
	offSig_sim_on:= dipar.SK_off.sim_on,
	offSig_sim_value := dipar.SK_off.sim_value,
	onFlt := dopar.SK_ON.flt);
dopar.SK_ON.value := am.SK.onOUT;
//--------------------------------------------------------------------------

//ДГ
//Тип: а
am.DG(
	PosSigFlt := aipar.DG_pos.flt,
	SetFlt := aopar.DG_set.flt,
	pos := aipar.DG_pos.value,
	pos_sim_on := aipar.DG_pos.sim_on,
	pos_sim_value := aipar.DG_pos.sim_value);
aopar.DG_set.value := am.DG.set_out;

 // Управление КПВ1, 5
dopar.KPV15_ON.value := ( am.KPV1.onOUT OR am.KPV5.onOut ) AND ( am.KPV1.DU AND am.KPV5.DU ) OR (( AOss.cmd_KPV15_ON OR AObs.cmd_KPV15_ON OR dopar.KPV15_ON.value ) AND NOT alg.V_000 );
// -----------------------------------

// Рп: Контроль ГР
PPU.Check_GR.value := (btn.GR.out OR NObs.finish OR HP.finish OR KPK.finish) OR PPU.Check_GR.value AND NOT (btn.HR.out OR btn.Repair.out OR btn.Start.out OR btn.Cancel.out OR alg.AO);

// Рп: Контроль ХР
PPU.Check_HR.value := (btn.HR.out OR btn.GR.out OR NObs.finish OR NOss.finish OR HP.finish OR KPK.finish) OR PPU.Check_HR.value AND NOT (btn.Repair.out OR btn.Start.out OR btn.Cancel.out OR alg.AO);

//Рп: Предпусковая готовность
check.btn := btn.HP.out OR btn.KPK.out OR btn.APK.out;
tch.PrepareStart.value := (check.btn OR tch.PrepareStart.value) AND NOT (btn.Start.out OR btn.Cancel.out OR mde.Repair);
   IF btn.HP.out THEN check.ready := ENUM_ReadyToStart.HP;
ELSIF btn.KPK.out THEN check.ready := ENUM_ReadyToStart.KPK;
ELSIF btn.APK.out THEN check.ready := ENUM_ReadyToStart.APK;
ELSIF NOT tch.PrepareStart.value THEN check.ready := ENUM_ReadyToStart.OFF;
END_IF;

//Рп: Сигналы готовности
tch.ReadyHP.value := ((check.ready = ENUM_ReadyToStart.HP AND tch.PrepareStart.value AND Check_SAU.finish) OR tch.ReadyHP.value) AND NOT (NOT (mde.GR OR mde.HR) OR btn.Cancel.out);
tch.ReadyKPK.value := ((check.ready = ENUM_ReadyToStart.KPK AND tch.PrepareStart.value AND Check_SAU.finish) OR tch.ReadyKPK.value) AND NOT (NOT (mde.GR OR mde.HR) OR btn.Cancel.out);
tch.ReadyAPK.value := ((check.ready = ENUM_ReadyToStart.APK AND tch.PrepareStart.value AND Check_SAU.finish) OR tch.ReadyAPK.value) AND NOT (NOT (mde.GR OR mde.HR) OR btn.Cancel.out);
check.ReadytoSF := tch.ReadyHP.value OR tch.ReadyKPK.value OR tch.ReadyAPK.value;


//Рп: Контроль САУ
//Проверка при подготовке к пуску или по кнопке при "Нет активных режимов" или каждые 12 часов, но не на пусковых режимах
check.tmr12H ( IN := NOT check.tmr12H.Q );
tch.Check_SAU.value := Check_SAU.drm.active;
check.tmrCancelPrm ( IN := Check_SAU.drm.active );
//Контроль виброаппаратуры двигателя (ИВ-Д-ПФ)
crs.Vs_D_Av.alg_check 	:= tch.Check_SAU.value;
crs.Vsst_HH.alg_check	:= tch.Check_SAU.value;
crs.Vstk_HH.alg_check	:= tch.Check_SAU.value;
crs.BZA_alr.alg_check	:= tch.Check_SAU.value;
dopar.Vibr_ctrl.value 	:= (Check_SAU.cmd_check_VibD OR dopar.Vibr_ctrl.value) AND NOT ( crs.Vs_D_Av.signalization AND crs.Vsst_HH.signalization AND crs.Vstk_HH.signalization OR btn.Cancel.out );
dopar.BZA_ctrl.value	:= (Check_SAU.cmd_check_BZA OR dopar.BZA_ctrl.value) AND NOT ( crs.BZA_alr.signalization OR btn.Cancel.out );
//tch.brk_vib_d.value := Check_SAU.cmd_check_VibD AND NOT (crs.VsPOD_OH.out AND crs.VsZOD_OH.out AND crs.VsD_Av.out);
//Разрешение старта
check.prm_start := (Check_SAU.finish AND check.ReadytoSF OR check.prm_start) AND NOT (btn.Start.out OR btn.Cancel.out OR mde.Repair);

//Имитация подрежима "Контроль САУ"
IF imitGPA.imit_on THEN check_imit(); END_IF;

check.tmrImit(IN := dopar.Vibr_ctrl.value OR dopar.BZA_ctrl.value);

dipar.Vs_D_Av.sim_value := check.tmrImit.Q;
dipar.BZA_alr.sim_value := check.tmrImit.Q;

aipar.Vstk.sim_value	:= TO_BYTE( check.tmrImit.Q ) * 92.0 + TO_REAL( SHR( PRG_base.result_time, 8) AND 2#00011111 ) * ( acpar.Ntk.value / Ntk );
aipar.Vsst.sim_value	:= aipar.Vstk.value;

