FUNCTION_BLOCK TAcparHandler
VAR_INPUT
	/// в секундах 
	cycle: REAL;
END_VAR
VAR
	/// обработчики частот вращения 
	nTKfilter1: TMedianLagFilter;
	nTKfilter2: TMedianLagFilter;
	nSTfilter1: TMedianLagFilter;
	nSTfilter2: TMedianLagFilter;
	nTKcalc: TFreqRotorHandler;
	nSTcalc: TFreqRotorHandler;
END_VAR
VAR_TEMP
	// Среднее алгебраическое значение температуры
	TstAverage: REAL;
	// Количество исправных каналов
	TstCount: BYTE;	
END_VAR

FUNCTION_BLOCK TAcparHandler
VAR_INPUT
	/// в секундах 
	cycle: REAL;
END_VAR
VAR
	/// обработчики частот вращения 
	nTKfilter1: TMedianLagFilter;
	nTKfilter2: TMedianLagFilter;
	nSTfilter1: TMedianLagFilter;
	nSTfilter2: TMedianLagFilter;
	nTKcalc: TFreqRotorHandler;
	nSTcalc: TFreqRotorHandler;
END_VAR
VAR_TEMP
	// Среднее алгебраическое значение температуры
	TstAverage: REAL;
	// Количество исправных каналов
	TstCount: BYTE;	
END_VAR

FUNCTION_BLOCK TAcparHandler
VAR_INPUT
	/// в секундах 
	cycle: REAL;
END_VAR
VAR
	/// обработчики частот вращения 
	nTKfilter1: TMedianLagFilter;
	nTKfilter2: TMedianLagFilter;
	nSTfilter1: TMedianLagFilter;
	nSTfilter2: TMedianLagFilter;
	nTKcalc: TFreqRotorHandler;
	nSTcalc: TFreqRotorHandler;
END_VAR
VAR_TEMP
	// Среднее алгебраическое значение температуры
	TstAverage: REAL;
	// Количество исправных каналов
	TstCount: BYTE;	
END_VAR

ST.xhtml:
(* фильтрация оборотов *)
(* нулевая постоянная времени фильтра тут корректна, при этом остается только медианный фильтр (чтобы убрать одиночные выбросы). 
При надобности можно увеличить tau, если нужен фильтр высокочастотной помехи (не отдельные "шилья", а "борода" на сигнале) *)
nTKfilter1( inVal:= aipar.Ntk_1.value, inBrk:= aipar.Ntk_1.flt, tau:= 0.3, cycle:= cycle ); 
nTKfilter2( inVal:= aipar.Ntk_2.value, inBrk:= aipar.Ntk_2.flt, tau:= 0.3, cycle:= cycle ); 
nSTfilter1( inVal:= aipar.Nst_1.value, inBrk:= aipar.Nst_1.flt, tau:= 0.3, cycle:= cycle ); 
nSTfilter2( inVal:= aipar.Nst_2.value, inBrk:= aipar.Nst_2.flt, tau:= 0.3, cycle:= cycle ); 

(* обработка двойных датчиков оборотов *)
nTKcalc.ch[1] 	:= nTKfilter1.outVal;
nTKcalc.ch[2]	:= nTKfilter2.outVal;
nTKcalc( disbal_Ch := 100.0, maxVal := aipar.Ntk_1.cfg.hilim, minVal := 100.0, ucvV := 500, flt_prm := acpar.Ntk.value > 500.0, deblock := btn.Unlock.out, out := acpar.Ntk );

nSTcalc.ch[1] 	:= nSTfilter1.outVal;
nSTcalc.ch[2]	:= nSTfilter2.outVal;
nSTcalc( disbal_Ch := 100.0, maxVal := aipar.Nst_1.cfg.hilim, minVal := 100.0, ucvV := 500, flt_prm := acpar.Nst.value > 500.0, deblock := btn.Unlock.out, out := acpar.Nst );

// обработка кольца термопар
{warning ' Убедиться, что в настройках модулей UCP1_A1_AI6 и UCP1_A1_AI7 выставлены диапазоны на каналах термопар (-50...+800) '}
// flt от модуля - обрыв или выход за пределы диапазона температур (-50...+800)
//TstCount := 0;
IF ( NOT aipar.Tg_inST_1.flt ) THEN
	TstAverage 	:= aipar.Tg_inST_1.value;
	TstCount 	:= 1;
END_IF
IF ( NOT aipar.Tg_inST_2.flt ) THEN
	TstAverage 	:= TstAverage + aipar.Tg_inST_2.value;
	TstCount	:= TstCount + 1;
END_IF
IF ( NOT aipar.Tg_inST_3.flt ) THEN
	TstAverage 	:= TstAverage + aipar.Tg_inST_3.value;
	TstCount	:= TstCount + 1;
END_IF
IF ( NOT aipar.Tg_inST_4.flt ) THEN
	TstAverage 	:= TstAverage + aipar.Tg_inST_4.value;
	TstCount	:= TstCount + 1;
END_IF
IF ( NOT aipar.Tg_inST_5.flt ) THEN
	TstAverage 	:= TstAverage + aipar.Tg_inST_5.value;
	TstCount	:= TstCount + 1;
END_IF
IF ( NOT aipar.Tg_inST_6.flt ) THEN
	TstAverage 	:= TstAverage + aipar.Tg_inST_6.value;
	TstCount	:= TstCount + 1;
END_IF

acpar.Tg_inST.flt 	:= TstCount = 0;
alg.TstInWork		:= TstCount;

IF TstCount > 0 THEN
	acpar.Tg_inST.in_value	:= TstAverage / TstCount;	
END_IF

(* все полученные данные выкладываются на входы acpar, acpar обновляются в своей автоматически сформированной функции *)
//acpar.Ntk.in_value := nVDcalc.value; acpar.Ntk.flt := nVDcalc.disbalanse;
//acpar.Nst.in_value := nSTcalc.value; acpar.Nst.flt := nSTcalc.disbalanse;
IF NOT aipar.Ta_inK.flt THEN acpar.NtkPrived.in_value := acpar.Ntk.value * SQRT( 288.15 / ( aipar.Ta_inK.value + 273.15 ) );
ELSE acpar.NtkPrived.in_value := acpar.Ntk.value;
END_IF;
acpar.Qtg_m3.in_value := FuelReg.fReg.fuel;

