FUNCTION_BLOCK TAcparHandler
VAR_INPUT
	/// в секундах 
	cycle: REAL;
END_VAR
VAR
	/// обработчики частот вращения 
	nTKfilter1: TMedianLagFilter;
	nTKfilter2: TMedianLagFilter;
	nSTfilter1: TMedianLagFilter;
	nSTfilter2: TMedianLagFilter;
	nTKcalc: TFreqRotorHandler;
	nSTcalc: TFreqRotorHandler;
END_VAR
VAR_TEMP
	// Среднее алгебраическое значение температуры
	TstAverage: REAL;
	// Количество исправных каналов
	TstCount: BYTE;	
END_VAR

FUNCTION_BLOCK TMedianLagFilter
VAR_INPUT
	inVal: REAL;
	inBrk: BOOL;
	tau: REAL;
	cycle: REAL;
END_VAR
VAR_OUTPUT
	outVal: REAL := 0;
END_VAR
VAR
	inArr: ARRAY[0..2] OF REAL;
	idx: INT := 0;
	cnt: INT;
	minVal: REAL := 1000000;
	maxVal: REAL := -1000000;
	sum: REAL;
END_VAR

FUNCTION_BLOCK TMedianLagFilter
VAR_INPUT
	inVal: REAL;
	inBrk: BOOL;
	tau: REAL;
	cycle: REAL;
END_VAR
VAR_OUTPUT
	outVal: REAL := 0;
END_VAR
VAR
	inArr: ARRAY[0..2] OF REAL;
	idx: INT := 0;
	cnt: INT;
	minVal: REAL := 1000000;
	maxVal: REAL := -1000000;
	sum: REAL;
END_VAR

FUNCTION_BLOCK TMedianLagFilter
VAR_INPUT
	inVal: REAL;
	inBrk: BOOL;
	tau: REAL;
	cycle: REAL;
END_VAR
VAR_OUTPUT
	outVal: REAL := 0;
END_VAR
VAR
	inArr: ARRAY[0..2] OF REAL;
	idx: INT := 0;
	cnt: INT;
	minVal: REAL := 1000000;
	maxVal: REAL := -1000000;
	sum: REAL;
END_VAR

ST.xhtml:
IF inBrk THEN
	outVal := 0.0;
ELSE
  // заполнить входной массив, работает как кольцевой буфер
  inArr[ idx ] := inVal;
  idx := idx + 1;
  IF idx > 2 THEN idx := 0; END_IF;
  // сразу найти сумму - закладка под бОльщую размерность массива
  sum := 0.0;
  minVal := 1000000.0;
  maxVal := -1000000.0;
  FOR cnt := 0 TO 2 DO
	sum := sum + inArr[cnt];
    IF inArr[cnt] > maxVal THEN maxVal := inArr[cnt]; END_IF;  
    IF inArr[cnt] < minVal THEN minVal := inArr[cnt]; END_IF;  
  END_FOR
  // отбраковать минимум, максимум
  sum := sum - maxVal - minVal;
  // инерционное звено
  IF tau > cycle THEN
    outVal := outVal + ( cycle / tau ) * ( sum - outVal );	
  ELSE
	outVal := sum;   
  END_IF; 	
END_IF

