FUNCTION_BLOCK TMedianLagFilter
VAR_INPUT
	inVal: REAL;
	inBrk: BOOL;
	tau: REAL;
	cycle: REAL;
END_VAR
VAR_OUTPUT
	outVal: REAL := 0;
END_VAR
VAR
	inArr: ARRAY[0..2] OF REAL;
	idx: INT := 0;
	cnt: INT;
	minVal: REAL := 1000000;
	maxVal: REAL := -1000000;
	sum: REAL;
END_VAR

