ST.xhtml:
IF NOT init THEN // инициализациЯ - производитсЯ считывание настроек, модель устанавливаетсЯ в нулевое начальное состоЯние
    DUS_DZ        := tuns^.DUSdz;
    DUS_RATE      := tuns^.DUSrate; 
    NvdStart := tuns^.NvdStart;
	tSTtoTT := 1.35; 
    Gt0  := 0.0;
    nvd0 := 0.1;
    NvdSetStarter := tuns^.NvdStart;
    nVDset := 0.1;
    tSTset := 0.0;
    posDG1 := 0.0;
    posDG2 := 0.0;
    nsd := 0.0;
    nnd := 0.0;
    nst := 0.0;
    init:= true;
    stepQuantity := REAL_TO_DINT(cycle/step + 0.5);
  ELSE // основнаЯ работа
    FOR integCount := 1 TO stepQuantity DO 
      // моделирование привода ДУСа (основного и дополнительного)
      // дозаторы топлива имеют шаговый электропривод с высоким быстродействием.
      IF nvd0 < 0.1 THEN nvd0 := 0.1; END_IF;
// Упрощаем имитацию ДУСа
//      DUSmdl(set := setDUSmain, dz := 0.25, cycle := step); 
      //YDUSmain := DUSmdl.out;
//      YDUSmain := setDUSmain;
      IF ABS( setDG1 - posDG1 ) > DUS_DZ THEN
        posDG1 := posDG1 + (step/( 0.3 * 100.0 / tuns^.DUSrate ) ) * (setDG1 - posDG1);		  
      END_IF;   
(* 
      IF setDG1 - posDG1 > DUS_DZ THEN
        posDG1 := posDG1 + step*DUS_RATE;
        IF posDG1 > setDG1 THEN posDG1 := setDG1; END_IF;
      ELSIF setDG1 - posDG1 < -DUS_DZ THEN
        posDG1 := posDG1 -step*DUS_RATE;
        IF posDG1 < setDG1 THEN posDG1 := setDG1; END_IF;
      END_IF;
      // длЯ двухзонных камер сгораниЯ: многозонность горениЯ не учитываетсЯ, а просто учитываетсЯ суммарный расход 
      //топлива через два дозатора
      IF DUSaddPresent THEN
        IF setDG2 - posDG2 > DUS_DZ THEN
          posDG2 := posDG2 + step*DUS_RATE;
          IF posDG2 > setDG2 THEN posDG2 := setDG2; END_IF;
        ELSIF setDG2 - posDG2 < -DUS_DZ THEN
          posDG2 := posDG2 -step*DUS_RATE;
          IF posDG2 < setDG2 THEN posDG2 := setDG2; END_IF;
        END_IF;
      END_IF;
      *)
	  tuns^.openToGt( arg := posDG1 + posDG2 );
      Gt0 := (tuns^.openToGt.out) * TO_INT(NOT dipar.SK_off.value);

      tuns^.GtToNvd(arg := Gt0 );
      tuns^.NvdToTauNvd(arg := Nvd);

      IF Gt0 < 0.0 THEN Gt0 := 0.0; END_IF;
  //    IF DUSaddPresent THEN Gt0 := Gt0 + tunings(tunName := tunConst.YDUSaddToGt, arg := YDUSadd); END_IF;
      // расход топлива
      // момент стартера
      IF starter THEN
        IF elStart THEN
          IF starterSpeed1 THEN NvdSetStarter := NvdStart/ 2.0;
          ELSE NvdSetStarter := NvdStart; END_IF;              
          // добавлено моделирование различной мощности электростартера на первой и второй скорости 
          IF NvdSetStarter > tuns^.GtToNvd.out THEN 
            nVDset := NvdSetStarter;
          ELSE nVDset := tuns^.GtToNvd.out;
          END_IF;       
        ELSE    
          nVDset := NvdStart + tuns^.GtToNvd.out;
        END_IF;  
      ELSE    
        nVDset := tuns^.GtToNvd.out;    
      END_IF;  
      // электростартер имеет почти постоЯнные обороты, поэтому обгоннаЯ муфта его
      // отключает. Турбостартер передает момент на вал всегда, когда включен
      // зубчатой муфтой и к нему подведен пусковой газ
      nvd0 := nvd0 + (step/(tuns^.NvdToTauNvd.out+0.001)) * (nVDset - nvd0);
      // частота вращениЯ ротора высокого давлениЯ (приведеннаЯ)

      tuns^.GtToTst(arg := Gfuel);
      tuns^.NvdToTst(arg := Nvd);
      tuns^.NvdToTauTst(arg := Nvd);

      tSTset := Tatm + tuns^.GtToTst.out - tuns^.NvdToTst.out;
	  IF tSTset < 0.0 THEN tSTset := 0.0; END_IF;
      Tst := Tst + (step/tuns^.NvdToTauTst.out) * (tSTset - Tst);
      // температура продуктов сгораниЯ вычислЯетсЯ в зависимости от частоты вращениЯ (-) и расхода топлива (+), учитываетсЯ

      Tt0 := tuns^.GtToTst.out - tuns^.NvdToTst.out;
      Tt  := Tt + (Tt0 - Tt) / tuns^.NvdToTauTst.out * cycle;

     // динамика
      nvd := nvd0 * SQRT((273.15 + Tatm)/288.15);
   (*   IF NDpresent THEN
        IF SDpresent THEN
          nsd := nsd + (step/(tunings(tunName := tunConst.nsdToTauSD, arg := nsd)+0.001))*
            (tunings(tunName := tunConst.nvdToNsd, arg := nvd) - nsd);
          nnd := nnd + (step/(tunings(tunName := tunConst.nndToTauND, arg := nnd)+0.001))*
            (tunings(tunName := tunConst.nsdToNnd, arg := nsd) - nsd);
        ELSE
          nsd := 0.0;
          nnd := nnd + (step/(tunings(tunName := tunConst.nsdToTauSD, arg := nnd)+0.001))*
            (tunings(tunName := tunConst.nvdToNsd, arg := nvd) - nnd); 
        END_IF;  
      END_IF;  
      // такаЯ хитраЯ логика свЯзана с терминологией: на двухвальных газогенераторах есть роторы ВД и НД, а на трехвальных - 
      // ВД, СД и НД. Поэтому, при наличии только флага НД игнорируетсЯ СД, а НД вычислЯетсЯ как СД.
	  *)	  	  
      IF PkPresent THEN
		tuns^.NvdToPk(arg := Nvd);
        tuns^.NvdToTauPk(arg := Nvd);
        Pk := Pk + (step/(tuns^.NvdToTauPk.out + 0.001)) * (tuns^.NvdToPk.out - Pk);
      END_IF;        


      (* пока не нужно, пригодится для генератора  
      power := tunings(tunName := tunConst.nvdToPower, arg := nvd0);
	  *)
      Gfuel := Gt0;
      // А здесь скорость СТ подсчитаем по упрощённой модели
 	  tuns^.NvdToNst(arg := Nvd);
      tuns^.NstToTauNst(arg := Nst);
      nst := nst + (step/(tuns^.NstToTauNst.out+0.001))*
                         (tuns^.NvdToNst.out - nst);
    END_FOR;
  END_IF;

