/// Вентиляторы маслоохладителя
METHOD PRIVATE VnCntrl : BOOL
VAR
	index	: BYTE;
	min_	: BYTE := 1;
	max_	: BYTE := 1;
	on_1	: BOOL := TRUE;
	off_1	: BOOL := TRUE;
END_VAR

ST.xhtml:
FOR index := 1 TO 4 DO
	Vn_s[index]^.on 	:= Vn_s[index]^.notOn AND Vn_s[index]^.flt;
	Vn_s[index]^.off 	:= FALSE;
END_FOR

IF On THEN
	FOR index := 1 TO 4 DO
	IF Vn_s[index]^.DU OR Vn_s[index]^.on THEN CONTINUE; END_IF
	IF Vn_s[index]^.isOFF THEN
		IF on_1 THEN
			min_ := index;
			on_1 := FALSE;
		END_IF
		IF Vn_s[index]^.OperationTime <= Vn_s[min_]^.OperationTime THEN
			min_ := index;
		END_IF
	END_IF
	END_FOR

	Vn_s[min_]^.off:= FALSE;
	Vn_s[min_]^.on := NOT Vn_s[min_]^.isON;
END_IF

IF Off THEN
	FOR index := 1 TO 4 DO
	IF Vn_s[index]^.DU OR Vn_s[index]^.off THEN CONTINUE; END_IF
	IF Vn_s[index]^.setOn THEN
		IF off_1 THEN
			max_ := index;
			off_1 := FALSE;
		END_IF
		IF ( Vn_s[index]^.OperationTime >= Vn_s[max_]^.OperationTime ) THEN
			max_ := index;
		END_IF
	END_IF
	END_FOR

	Vn_s[max_]^.on	:= FALSE;
	Vn_s[max_]^.off := Vn_s[max_]^.setOn; //NOT Vn_s[max_]^.isOFF OR Vn_s[max_]^.notOn;
END_IF

