/// Chekmarev
METHOD update : BOOL
VAR_INPUT
	// регулируемая температура
	temperature	: REAL;
END_VAR
VAR
	// период следования импульсов
	T: TIME := TIME#1m0s0ms;
END_VAR

/// Chekmarev
METHOD update : BOOL
VAR_INPUT
	// регулируемая температура
	temperature	: REAL;
END_VAR
VAR
	// период следования импульсов
	T: TIME := TIME#1m0s0ms;
END_VAR

ST.xhtml:
PIDreg(temperature := temperature);

// Шаг импульса зависит от величины коррекции ошибки ПИД регулятором
// ( реализация ЧИМ )
T := TO_TIME (( 110 - ABS ( TmReg.out )) * 1000 );

tmrT ( in := NOT tmrT.Q, PT := T );

// Выделяем передний фронт импульса выхода таймера
IF (( tmrT.Q XOR tmrT_Qold ) AND tmrT.Q ) THEN
	IF ( 0 < tmreg.out - _DZ ) THEN
		_On 	:= TRUE;	// снимается в акцессоре
		_Off	:= FALSE;	// снимем на всякий случай
	END_IF

	IF ( 0 >= tmreg.out + _DZ ) THEN
		_On		:= FALSE;	// снимем на всякий случай
		_Off	:= TRUE;	// снимается в акцессоре
	END_IF
END_IF

tmrT_Qold := tmrT.Q;

IF NOT enable THEN
	_On	:= FALSE;
	_Off:= TRUE;
END_IF

VnCntrl();

