PROGRAM PRG_PRU_Base
VAR_INPUT

	General: ARRAY[0..1] OF WORD := [4, 0];	/// номер агрегата [0] и режимх[1] 
	Holdings: ARRAY[0..16] OF REAL;
	Coils: ARRAY[0..13] OF BYTE;
	StatusReal: WORD;
