VAR	
	Count: BYTE;	/// счётчик ошибок связи с ПРУ
	LinkPSU: BOOL;
	LinkPSUold: BOOL;
END_VAR

ST.xhtml:
// Контроль связи с ПСУ
LinkPSU	:= Coils[13].1 XOR Coils[13].0;
IF LinkPSU THEN
	Count := Count + 1;
	ELSE
	Count := 0;
	PRU.Link := TRUE;
	LinkPSUold		:= NOT LinkPSUold;
END_IF

IF Count > 254 THEN 
	PRU.Link 	:= FALSE; 
	Count 		:= 1;
//	LinkPSUold		:= NOT LinkPSUold;
END_IF;

Coils[13].0	:= LinkPSUold;

// Кнопки
btn.AOss.cmd_PRU	:= Coils[0].0;//btn_AOss_Кнопка "АОсс"
btn.AObs.cmd_PRU	:= Coils[0].1;//btn_AObs_Кнопка "АОбс"
btn.NOss.cmd_PRU	:= Coils[0].2;//btn_NOss_Кнопка "НОсс"
btn.NObs.cmd_PRU	:= Coils[0].3;//btn_NObs_Кнопка "НОбс"
btn.turnUP.cmd_PRU	:= Coils[0].4;//btn_turnUP_Кнопка "Увеличить обороты"
btn.turnDN.cmd_PRU	:= Coils[0].5;//btn_turnDN_Кнопка "Уменьшить обороты"

//Coils[0].6;//btn_regNvd_Кнопка "Регулирование оборотов ВД"
//Coils[0].7;//btn_regNst_Кнопка "Регулирование оборотов СТ"
