//Coils[1].1;//prm_AObs_Разрешение кнопки "АОбс"
//Coils[1].2;//prm_NOss_Разрешение кнопки "НОсс"
//Coils[1].3;//prm_NObs_Разрешение кнопки "НОбс"
Coils[1].4 := btn.turnUP.prm;//prm_turnUP_Разрешение кнопки "Увеличить обороты"
Coils[1].5 := btn.turnDN.prm;//prm_turnDN_Разрешение кнопки "Уменьшить обороты"
//Coils[1].6;//prm_regNvd_Разрешение кнопки "Регулирование оборотов ВД"
Coils[1].7 := btn.turnUP.prm OR btn.turnDN.prm;//prm_regNst_Разрешение кнопки "Регулирование оборотов СТ"

// ИМы
Coils[4].0		:= am.SK.isON;//NOT dipar_SK_OF_СК открыт
Coils[4].1		:= am.kr1.isON;//dipar_Kr1_ON_Кран КШ1 открыт
Coils[4].2		:= am.Kr1.isOFF;//dipar_Kr1_OF_Кран КШ1 закрыт
Coils[4].3		:= am.Kr2.isON;//dipar_Kr2_ON_Кран КШ2 открыт
Coils[4].4		:= am.Kr2.isOFF;//dipar_Kr2_OF_Кран КШ2 закрыт
Coils[4].5		:= am.Kr4.isON;//dipar_Kr4_ON_Кран КШ4 открыт
Coils[4].6		:= am.Kr4.isOFF;//dipar_Kr4_OF_Кран КШ4 закрыт
Coils[4].7		:= am.Kr5.isON;//dipar_Kr5_ON_Кран КШ5 открыт
Coils[5].0		:= am.Kr5.isOFF;//dipar_Kr5_OF_Кран КШ5 закрыт
Coils[5].1		:= am.Kr6.isON;//dipar_Kr6_ON_Кран КШ6 открыт
Coils[5].2		:= am.Kr6.isOFF;//dipar_Kr6_OF_Кран КШ6 закрыт
Coils[5].3		:= am.Kr9.isON;//dipar_Kr13_ON_Кран КШ13 открыт
Coils[5].4		:= am.Kr9.isOFF;//dipar_Kr13_OF_Кран КШ13 закрыт
Coils[5].5		:= am.Kr12.isON;//dipar_Kr14_ON_Кран КШ14 открыт
Coils[5].6		:= am.Kr12.isOFF;//dipar_Kr14_OF_Кран КШ14 закрыт

// Статусы подсистем
Coils[7].0	:= subsystem.EXT.nrml;	// status_EXT_nrml Внешние сигналы_норма
Coils[7].1	:= subsystem.EXT.alr;	// status_EXT_alr Внешние сигналы_предупрежденеие
Coils[7].2	:= subsystem.EXT.crs;	// status_EXT_crs Внешние сигналы_авария
