Coils[7].4	:= subsystem.BD.alr;	// status_BD_alr Блок двигателя_предупрежденеие
Coils[7].5	:= subsystem.BD.crs;	// status_BD_crs Блок двигателя_авария
Coils[7].6	:= subsystem.MSD.nrml;	// status_MSD_nrml Маслосистема двигателя_норма
Coils[7].7	:= subsystem.MSD.alr;	// status_MSD_alr Маслосистема двигателя_предупрежденеие
Coils[8].0	:= subsystem.MSD.crs;	// status_MSD_crs Маслосистема двигателя_авария
Coils[8].1	:= subsystem.BTG.nrml;	// status_BTG_nrml Блок топливного газа_норма
Coils[8].2	:= subsystem.BTG.alr;	// status_BTG_alr Блок топливного газа_предупрежденеие
Coils[8].3	:= subsystem.BTG.crs;	//status_BTG_crs Блок топливного газа_авария
