Coils[8].5	:= subsystem.AVOM.alr;//status_AVOMD_alr АВОМД_предупрежденеие
Coils[8].6	:= subsystem.AVOM.crs;//status_AVOMD_crs АВОМД_авария
Coils[8].7	:= subsystem.BN.nrml;//status_BN_nrml Блок нагнетателя_норма
Coils[9].0	:= subsystem.BN.alr;//status_BN_alr Блок нагнетателя_предупрежденеие
Coils[9].1	:= subsystem.BN.crs;//status_BN_crs Блок нагнетателя_авария
Coils[9].2	:= subsystem.GO.nrml;//status_GO_nrml Газовая обвязка_норма
Coils[9].3	:= subsystem.GO.alr;//status_GO_alr Газовая обвязка_предупрежденеие
Coils[9].4	:= subsystem.GO.crs;//status_GO_crs Газовая обвязка_авария
Coils[9].5	:= subsystem.VS.nrml;//status_VS_nrml Воздушный стартер_норма
Coils[9].6	:= subsystem.VS.alr;//status_VS_alr Воздушный стартер_предупрежденеие
Coils[9].7	:= subsystem.VS.crs;//status_VS_crs Воздушный стартер_авария
Coils[10].0	:= subsystem.BPG.nrml;//status_BPG_nrml Блок пускового газа_норма
Coils[10].1	:= subsystem.BPG.alr;//status_BPG_alr Блок пускового газа_предупрежденеие
Coils[10].2	:= subsystem.BPG.crs;//status_BPG_crs Блок пускового газа_авария
Coils[10].3	:= subsystem.POS.nrml;//status_POS_nrml ПОС ВОУ_норма
Coils[10].4	:= subsystem.POS.alr;//status_POS_alr ПОС ВОУ_предупрежденеие
Coils[10].5	:= subsystem.POS.crs;//status_POS_crs ПОС ВОУ_авария
Coils[10].6	:= subsystem.BU.nrml;//status_BU_nrml Блок автоматики_норма
Coils[10].7	:= subsystem.BU.alr;//status_BU_alr Блок автоматики_предупрежденеие
Coils[11].0	:= subsystem.BU.crs;//status_BU_crs Блок автоматики_авария


// Режим агрегата
General[1]			:= mde.number;

// Аналоги
//Holdings[1]		:= am.APK.pos; 				// aipar_APK_Pos_Положение клапана АПК1		// 2
//StatusReal.0	:= am.APK.flt;
//Holdings[2]		:= 0;			// aipar_reserve									// 4

//Holdings[3]		:= acpar.Ntk.value;		// acpar_evNnd_Расчётная Ntk				// 6
//StatusReal.2	:= acpar.Ntk.flt;

Holdings[4]		:= acpar.Ntk.value;		// acpar_evNvd_Расчётная Ntk				// 8
StatusReal.3	:= acpar.Nst.flt;

Holdings[5]		:= acpar.Nst.value;		// acpar_evNst_Расчётная Nст				// 10
StatusReal.4	:= acpar.Nst.flt;

Holdings[6]		:= aipar.Pg_inN.value;	// acpar_evPg_inN P газа на входе в компрессор		// 12
StatusReal.5	:= aipar.Pg_inN.flt;

Holdings[7]		:= aipar.Pg_outN.value;	// acpar_evPg_outN P газа на выходе из компрессора	// 14
StatusReal.6	:= aipar.Pg_outN.flt;

Holdings[8]		:= aipar.Tg_inN.value;	// acpar_evTg_inN T газа на входе в компрессор		// 16
StatusReal.7	:= aipar.Tg_inN.flt;

Holdings[9]		:= aipar.Tg_outN.value;	// acpar_evTg_outN T газа на выходе из компрессора	// 18
StatusReal.8	:= aipar.Tg_outN.flt;

//Holdings[10]	:= acpar.evdPg_conf.value;	// acpar_evdPg_conf_Расчётная dP газа на аннубар				// 20
//StatusReal.9	:= acpar.evdPg_conf.flt;

Holdings[11]	:= acpar.Tg_inST.value;	// acpar_evTg_outTND_Расчётная Т газа перед СТ					// 22
StatusReal.10	:= acpar.Tg_inST.flt;

//Holdings[12]	:= aipar.Ta_Angar.value;	// acpar_evTa_BN_Расчётная T воздуха в укрытии Компрессора		// 24
