Holdings[13]	:= aipar.Ta_inK.value;		// acpar_evTa_inBD_Расчётная T воздуха в блоке двигателя		// 26
StatusReal.12	:= aipar.Ta_inK.flt;

//Holdings[14]	:= s_aspar.surgeRes.value;	// acpar_Surge_Помпажный запас									// 28					
//StatusReal.13	:= s_aspar.surgeRes.flt;

IF aipar.Pg_inN.value > 0.0 THEN
	Holdings[15]	:= aipar.Pg_outN.value / aipar.Pg_inN.value;	// acpar_PR_Степень сжатия // 30
	ELSE 
		Holdings[15] := 0;
END_IF								
StatusReal.14	:= aipar.Pg_outN.flt OR aipar.Pg_inN.flt;		// s_aspar.evPR.flt;

Holdings[16]	:= aipar.Ptg_inTRK.value;	// aipar_Ptg_inD_Р топливного газа на вх. в Д	// 32
StatusReal.15	:= aipar.Ptg_inTRK.flt;

(*
Holdings[1]		:= Holdings[1] + 0.1; 				// aipar_APK_Pos_Положение клапана АПК1		// 2
//Holdings[2]		:= 0;			// aipar_reserve									// 4
Holdings[3]		:= Holdings[3] + 1; 			// acpar_evNnd_Расчётная Nвд							// 6
Holdings[4]		:= 3400;		// acpar_evNvd_Расчётная Nнд				// 8
Holdings[5]		:= 3001;		// acpar_evNst_Расчётная Nст				// 10
Holdings[6]		:= 6.6;	// acpar_evPg_inN_Расчётное P газа на входе в компрессор		// 12
Holdings[7]		:= 7.7;	// acpar_evPg_outN_Расчётное P газа на выходе из компрессора	// 14
Holdings[8]		:= 34.3;	// acpar_evTg_inN_Расчётная T газа на входе в компрессор		// 16
Holdings[9]		:= 87.9;	// acpar_evTg_outN_Расчётная T газа на выходе из компрессора	// 18
Holdings[10]	:= 20.01;	// acpar_evdPg_conf_Расчётная dP газа на аннубар				// 20
Holdings[11]	:= 470;	// acpar_evTg_outTND_Расчётная Т газа перед СТ					// 22
Holdings[12]	:= 22.12;	// acpar_evTa_BN_Расчётная T воздуха в укрытии Компрессора		// 24
Holdings[13]	:= 23.13;		// acpar_evTa_inBD_Расчётная T воздуха в блоке двигателя		// 26
Holdings[14]	:= 67.0;//	acpar. acpar_Surge_Помпажный запас									// 28					
Holdings[15]	:= 0.22;//acpar.PR; acpar_PR_Степень сжатия									// 30
Holdings[16]	:= 19.16;	// aipar_Ptg_inD_Р топливного газа на вх. в Д	// 32
