PROGRAM PRG_PRU_TimeSync
VAR
	///  Год, Месяц, День, час, минуты,секунды
	TimeAndDate: ARRAY[0..6] OF WORD;
	UnixTimems: DWORD;
	pres: UDINT;
	pDate: PsTime.SYSTIMEDATE;
END_VAR
VAR CONSTANT
	/// временная зона (в ПРУ Овен отсутствует)
	TimeZone: BYTE := 3;
END_VAR

PROGRAM PRG_PRU_TimeSync
VAR
	///  Год, Месяц, День, час, минуты,секунды
	TimeAndDate: ARRAY[0..6] OF WORD;
	UnixTimems: DWORD;
	pres: UDINT;
	pDate: PsTime.SYSTIMEDATE;
END_VAR
VAR CONSTANT
	/// временная зона (в ПРУ Овен отсутствует)
	TimeZone: BYTE := 3;
END_VAR

ST.xhtml:
// ---- Синхронизация времени
UnixTimems	:= PsTime.SysTimeRtcGet(pres);
PsTime.SysTimeRtcConvertUtcToDate(UnixTimems, pDate);

TimeAndDate[0]	:= pDate.wYear;				// Год
TimeAndDate[1]	:= pDate.wMonth;			// Месяц
TimeAndDate[2]	:= pDate.wDay;				// День
TimeAndDate[3]	:= pDate.wHour + TimeZone;	// Час
TimeAndDate[4]	:= pDate.wMinute;			// Минуты
TimeAndDate[5]	:= pDate.wSecond;			// Секунды

TimeAndDate[6]	:= 1;		// Признак готовности времени для синхронизации (признак снимается с ПРУ)

// ----

