subsystem.AVOM(
	goWork	:= am.Vn1_AVOM.on OR am.Vn2_AVOM.on OR am.Vn3_AVOM.on OR am.Vn4_AVOM.on,
	goStop	:= NOT ( am.Vn1_AVOM.on OR am.Vn2_AVOM.on OR am.Vn3_AVOM.on OR am.Vn4_AVOM.on ),
	work := am.Vn1_AVOM.isON OR am.Vn2_AVOM.isON OR am.Vn3_AVOM.isON OR am.Vn4_AVOM.isON,
	stop  := NOT ( am.Vn1_AVOM.isON OR am.Vn2_AVOM.isON OR am.Vn3_AVOM.isON OR am.Vn4_AVOM.isON )
);

//enable	:= mde.APK OR alg.work OR alg.NO OR am.PNU.isON OR am.PNS.isON;

avom.AVOM.enable	:= ( avom.AVOM.enable OR fuelreg.fReg.isFire ) AND NOT ( alg.V_000 AND am.PNS.isOFF AND am.PNU.isOFF ); 

temperature := MAX ( aipar.Tm_inD.value, aipar.Tm_outAU.value, aipar.Tm_outAVOM.value );
AVOM.AVOM.update( temperature := temperature );
IF imitGPA.imit_on THEN AVOM_imit(); END_IF;

temp := MAX (aipar.Tm_outD.value, aipar.Ta_inK.value);
aipar.Tm_outAVOM.sim_value	:= aipar.Tm_outAVOM.sim_value + ( temp - ( temp - aipar.Ta_inK.value) * ( TO_BYTE ( am.Vn1_AVOM.isON ) + TO_BYTE ( am.Vn2_AVOM.isON ) + TO_BYTE ( am.Vn3_AVOM.isON ) + TO_BYTE ( am.Vn4_AVOM.isON )) * 0.95 / 4 - aipar.Tm_outAVOM.sim_value ) / tau_Nto0;
aipar.Tm_outAU.sim_value 	:= aipar.Ta_inK.value;

subsystem.BTG();

ALG_BTG_AM();

IF imitGPA.imit_on THEN BTG_imit(); END_IF;

subsystem.MSD();

ALG_MSD_AM();

IF imitGPA.imit_on THEN MSD_imit(); END_IF;

InterfaceAsPlainText.xhtml:
