VAR CONSTANT
	dPmg_PNU: REAL := 0.7;
	dpmg_BN: REAL := 2.5;
	Nst_norm: REAL := 8500;
END_VAR

FUNCTION MSD_Imit : BOOL
VAR CONSTANT
	dPmg_PNU: REAL := 0.7;
	dpmg_BN: REAL := 2.5;
	Nst_norm: REAL := 8500;
END_VAR

ST.xhtml:
tmr.PNU_S_Off.IN 	:= ( NOss.cmd_PNU_S_Off OR AOss.cmd_PNU_S_Off OR Bleeding_full.cmd_PNU_S_Off OR tmr.PNU_S_Off.IN ) AND NOT ( tmr.PNU_S_Off.Q OR tch.Gas_N.value );
tmr.PNU_S_pumpH.IN	:= ( tch.GTDcool.value OR tch.GTDHeat.value ) AND dipar.Pm_N_Pn.value;

am.PNS.on	:= HP.cmd_PNU_S_On OR KPK.cmd_PNU_S_On OR APK.cmd_PNU_S_On OR NOss.cmd_PNU_S_On OR NObs.cmd_PNU_S_On OR AOss.cmd_PNU_S_On OR AObs.cmd_PNU_S_On OR ( mde.GR AND am.PNS.isOFF ) OR tmr.PNU_S_pumpH.IN;
am.PNS.off	:= (( HP.cmd_PNS_Off OR ( mde.HR OR mde.Repair ) AND am.PNS.isON AND tch.nGas_N.value ) AND NOT tmr.PNU_S_Off.IN ) OR Start_D.cmd_PNS_Off OR ( tmr.PNU_S_Off.Q AND tch.nGas_N.value ) OR (( tch.GTDcool.value OR tch.GTDHeat.value OR alg.work ) AND NOT tmr.PNU_S_pumpH.Q AND am.PNS.isON );

am.PNU.on	:= HP.cmd_PNU_S_On OR KPK.cmd_PNU_S_On OR APK.cmd_PNU_S_On OR NOss.cmd_PNU_S_On OR NObs.cmd_PNU_S_On OR AOss.cmd_PNU_S_On OR AObs.cmd_PNU_S_On OR ( mde.GR AND am.PNU.isOFF ) OR tmr.PNU_S_pumpH.IN;
am.PNU.off	:= (( HP.cmd_PNU_Off OR ( mde.HR OR mde.Repair ) AND am.PNU.isON AND tch.nGas_N.value ) AND NOT tmr.PNU_S_Off.IN ) OR Start_D.cmd_PNU_Off OR ( tmr.PNU_S_Off.Q AND tch.nGas_N.value ) OR (( tch.GTDcool.value OR tch.GTDHeat.value OR alg.work ) AND NOT tmr.PNU_S_pumpH.Q AND am.PNU.isON );

// Обогрев маслобака системы смазки
engine.ENBDN( par_value := aipar.Tm_MB.value, par_brk := aipar.Tm_MB.flt, setpoint_value := tunpar.setTmMBDN.value );
engine.ENBDN_HR( par_value := aipar.Tm_MB.value, par_brk := aipar.Tm_MB.flt );
//am.ENBDN.on	:= ( engine.ENBDN_HR.out AND tch.Check_HR.value ) OR engine.ENBDN.out AND NOT ( mde.Repair OR ( mde.HR AND NOT tch.Check_GR.value )) AND alg.reserve; //черепанов добавил alg.reserve

// Обогрев маслобака системы уплотнений
bn.ENBN( par_value := aipar.Tm_MBU.value, par_brk := aipar.Tm_MBU.flt, setpoint_value := tunpar.setTmMBN.value );
bn.ENBN_HR( par_value := aipar.Tm_MBU.value, par_brk := aipar.Tm_MBU.flt );
//am.ENBN.on := ( bn.ENBN_HR.out AND ppu.Check_HR.value ) OR bn.ENBN.out AND NOT ( mde.Repair OR ( mde.HR AND NOT ppu.Check_GR.value )) AND alg.reserve; //черепанов добавил alg.reserve

am.Kr11.on	:= HP.cmd_KR11_On OR Start_D.cmd_KR11_On;
am.Kr11.off	:= HP.cmd_KR11_Off OR Start_D.cmd_KR11_Off OR AOss.cmd_KR11_Off OR AObs.cmd_KR11_Off;

am.Kr10.on	:= am.Kr11.off;
am.Kr10.off	:= am.Kr11.on;

//dopar.Kr10m_ON.value := am.Kr11.on OR am.Kr11.off;
//dopar.Kr11m_ON.value := dopar.Kr11m_ON.value;

subsystem.BPG();

ALG_BPG_AM();

IF imitGPA.imit_on THEN BPG_imit(); END_IF;

subsystem.VS(
	goWork	:= am.Kr13.on,
	goStop	:= NOT am.Kr13.on,
	work 	:= am.Kr13.isON,
	stop	:= NOT am.Kr13.isOn
);

ALG_VS_AM();

am.Kr12.on	:= KPK.cmd_KR12_On OR Start_D.cmd_KR12_On;
am.Kr12.off	:= KPK.cmd_KR12_Off OR NOss.cmd_KR12_Off OR NObs.cmd_KR12_Off OR AOss.cmd_KR12_Off OR AObs.cmd_KR12_Off;

am.Kr9.on	:= am.Kr12.off;
am.Kr9.off	:= am.Kr12.on;

//dopar.KR9m_ON.value := am.Kr12.on OR am.Kr12.off;
//dopar.KR12m_ON.value := dopar.KR9m_ON.value;

//Собираем переходы для визуализации
drm.transition.0 := start := btn.test_on.out; //Запуск последовательности (0→1): Кнопка "Комплексное тестирование включить"
drm.transition.1 := TRUE; //1→2: Логическая 1
drm.transition.2 := mde.GR; //2→3: Режим ГР
drm.transition.3 := btn.start.prm; //3→4: Разрешение кнопки "Пуск"
drm.transition.4 := HP.finish; //4→5: Последовательность "ХП" завершена
drm.transition.5 := btn.start.prm; //5→6: Разрешение кнопки "Пуск"
drm.transition.6 := KPK.finish; //6→7: Последовательность "КПК" завершена
drm.transition.7 := btn.start.prm; //7→8: Разрешение кнопки "Пуск"
drm.transition.8 := APK.finish; //8→9: Последовательность "АПК" завершена
drm.transition.9 := AOss.finish; //9→10: Последовательность "АОсс" завершена
drm.transition.10 := mde.Repair; //10→11: Режим Ремонт
drm.transition.11 := mde.GR; //11→12: Режим ГР
drm.transition.12 := btn.start.prm; //12→13: Разрешение кнопки "Пуск"
drm.transition.13 := APK.finish; //13→14: Последовательность "АПК" завершена
drm.transition.14 := NOss.finish; //14→15: Последовательность "НОсс" завершена
drm.transition.15 := mde.GR; //15→16: Режим ГР
drm.transition.16 := AObs.finish; //16→17: Последовательность "АОбс" завершена
drm.transition.17 := mde.Repair; //17→18: Режим Ремонт
drm.transition.18 := M_K.finish; //18→19: Последовательность "Переход М-К" завершена
drm.transition.19 := acpar.Nst.value > 4990; //19→20: Nст > 4990 об/мин
drm.transition.20 := K_M.finish; //20→21: Последовательность "Переход К-М" завершена
drm.transition.21 := NObs.finish; //21→22: Последовательность "НОбс" завершена
drm.transition.22 := Bleeding_full.finish; //22→23: Последовательность "Стравливание" завершена
drm.transition.23 := mde.Repair; //23→24: Режим Ремонт
drm.transition.24 := btn.test_off.out; //24→0: Кнопка "Комплексное тестирование отключить"
drm.transition.31 := break := btn.test_off.out; //Принудительный выход из последовательности (N→0): Кнопка "Комплексное тестирование отключить"

//Вызываем экземпляр интерфейсного функционального блока
drm(cycle := cycle);

CASE drm.step OF
-1:	//Сброс команд с предыдущих шагов
	finish := FALSE;
	//Условие запуска последовательности
	//Кнопка "Комплексное тестирование включить"
	IF start AND NOT break THEN drm.step := 1; END_IF;
1:	//Запись уставки таймера шага
	drm.step := 1;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) init := drm.cmd.0 := drm.step_time <= cycle; //Переинициализирование переменных

	//Условие перехода (1)→(2)
	//Логическая 1
	IF (TRUE) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 2;
		init := FALSE; //Переинициализирование переменных
	END_IF;
2:	//Запись уставки таймера шага
	drm.step := 2;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
