	//Условие перехода (7)→(8)
	//Разрешение кнопки "Пуск"
	IF (btn.start.prm) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 8;
		btn.APK.cmd := FALSE; //Шаг проверки: АПК из ГР под газом // Кнопка "АПК"
	END_IF;
8:	//Запись уставки таймера шага
	drm.step := 8;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.Start.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АПК из ГР под газом // Кнопка "Пуск"

	//Условие перехода (8)→(9)
