	drm.step := 10;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) btn.Unlock.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АОсс из Кольца // Кнопка "Деблокировка"

	//Условие перехода (10)→(11)
