	(*1*) btn.GR.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АПК из ГР без газа // Кнопка "ГР"

	//Условие перехода (11)→(12)
	//Режим ГР
	IF (mde.GR) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 12;
		btn.GR.cmd := FALSE; //Шаг проверки: АПК из ГР без газа // Кнопка "ГР"
	END_IF;
12:	//Запись уставки таймера шага
	drm.step := 12;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.APK.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АПК из ГР без газа // Кнопка "АПК"

	//Условие перехода (12)→(13)
	//Разрешение кнопки "Пуск"
