		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 13;
		btn.APK.cmd := FALSE; //Шаг проверки: АПК из ГР без газа // Кнопка "АПК"
	END_IF;
13:	//Запись уставки таймера шага
	drm.step := 13;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.Start.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АПК из ГР без газа // Кнопка "Пуск"

	//Условие перехода (13)→(14)
	//Последовательность "АПК" завершена
	IF (APK.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 14;
		btn.Start.cmd := FALSE; //Шаг проверки: АПК из ГР без газа // Кнопка "Пуск"
