	drm.step := 14;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.NOss.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: НОсс из Кольца // Кнопка "НОсс"

	//Условие перехода (14)→(15)
	//Последовательность "НОсс" завершена
	IF (NOss.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 15;
		btn.NOss.cmd := FALSE; //Шаг проверки: НОсс из Кольца // Кнопка "НОсс"
	END_IF;
15:	//Запись уставки таймера шага
	drm.step := 15;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) btn.GR.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АПМ из ГР без газа // Кнопка "ГР"

	//Условие перехода (15)→(16)
	//Режим ГР
	IF (mde.GR) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 16;
		btn.GR.cmd := FALSE; //Шаг проверки: АПМ из ГР без газа // Кнопка "ГР"
	END_IF;
16:	//Запись уставки таймера шага
	drm.step := 16;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.AObs.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АОбс из Магистрали // Кнопка "АОбс"

	//Условие перехода (16)→(17)
	//Последовательность "АОбс" завершена
	IF (AObs.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 17;
		btn.AObs.cmd := FALSE; //Шаг проверки: АОбс из Магистрали // Кнопка "АОбс"
	END_IF;
17:	//Запись уставки таймера шага
	drm.step := 17;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) btn.Unlock.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АОбс из Магистрали // Кнопка "Деблокировка"

	//Условие перехода (17)→(18)
	//Режим Ремонт
	IF (mde.Repair) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 18;
		btn.Unlock.cmd := FALSE; //Шаг проверки: АОбс из Магистрали // Кнопка "Деблокировка"
	END_IF;
18:	//Запись уставки таймера шага
	drm.step := 18;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.M_K.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: Переход М-К // Кнопка "Переход М-К"

	//Условие перехода (18)→(19)
	//Последовательность "Переход М-К" завершена
	IF (M_K.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 19;
		btn.M_K.cmd := FALSE; //Шаг проверки: Переход М-К // Кнопка "Переход М-К"
	END_IF;
19:	//Запись уставки таймера шага
	drm.step := 19;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) cmd_Nst_5000 := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: Повышение Nст до 5000 об/мин
	(*1*) drm.error.0 := acpar.Nst.value < 5000; //Nст < 5000 об/мин

	//Условие перехода (19)→(20)
	//Nст > 4990 об/мин
	IF (acpar.Nst.value > 4990) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 20;
		cmd_Nst_5000 := FALSE; //Шаг проверки: Повышение Nст до 5000 об/мин
	END_IF;
20:	//Запись уставки таймера шага
	drm.step := 20;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.K_M.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: Переход К-М // Кнопка "Переход К-М"

	//Условие перехода (20)→(21)
	//Последовательность "Переход К-М" завершена
	IF (K_M.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 21;
		btn.K_M.cmd := FALSE; //Шаг проверки: Переход К-М // Кнопка "Переход К-М"
	END_IF;
21:	//Запись уставки таймера шага
	drm.step := 21;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.NObs.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: АОбс из Магистрали // Кнопка "НОбс"

	//Условие перехода (21)→(22)
	//Последовательность "НОбс" завершена
	IF (NObs.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 22;
		btn.NObs.cmd := FALSE; //Шаг проверки: АОбс из Магистрали // Кнопка "НОбс"
	END_IF;
22:	//Запись уставки таймера шага
	drm.step := 22;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) btn.Bleeding.cmd := drm.cmd.0 := TRUE; //Шаг проверки: Стравливание из ГР под газом // Кнопка "Стравливание ЦБК"

	//Условие перехода (22)→(23)
	//Последовательность "Стравливание" завершена
	IF (Bleeding_full.finish) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 23;
		btn.Bleeding.cmd := FALSE; //Шаг проверки: Стравливание из ГР под газом // Кнопка "Стравливание ЦБК"
	END_IF;
23:	//Запись уставки таймера шага
	drm.step := 23;//Текущий шаг
	drm.timer_pt := 10; //Таймер: 10 секунд

	//Команды текущего шага
	(*1*) btn.Repair.cmd := drm.cmd.0 := drm.step_time <= cycle; //Шаг проверки: Переход в Ремонт // Кнопка "Ремонт"

	//Условие перехода (23)→(24)
	//Режим Ремонт
	IF (mde.Repair) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := 24;
		btn.Repair.cmd := FALSE; //Шаг проверки: Переход в Ремонт // Кнопка "Ремонт"
	END_IF;
24:	//Запись уставки таймера шага
	drm.step := 24;//Текущий шаг
	drm.timer_pt := cycle; //Таймер: один цикл вызова

	//Команды текущего шага
	(*1*) finish := drm.cmd.0 := TRUE; //Завершение
	(*1*) drm.error.0 := NOT btn.test_off.out; //Нажмите кнопку "Комплексное тестирование отключить"

	//Условие перехода (24)→(0)
	//Кнопка "Комплексное тестирование отключить"
	IF (btn.test_off.out) AND drm.timeout THEN
		drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE; drm.step := -1;
		finish := FALSE; //Завершение
	END_IF;
END_CASE

//Принудительный выход из последовательности
IF break THEN
	drm.step := -1; drm.cmd := drm.error := 0; drm.timer_pt := cycle; drm.inc := FALSE;
	init := FALSE; //Переинициализирование переменных
	btn.GR.cmd := FALSE; //Шаг проверки: ХП из ГР // Кнопка "ГР"
	btn.HP.cmd := FALSE; //Шаг проверки: ХП из ГР // Кнопка "ХП"
	btn.Start.cmd := FALSE; //Шаг проверки: ХП из ГР // Кнопка "Пуск"
	btn.KPK.cmd := FALSE; //Шаг проверки: КПК из ГР // Кнопка "КПК"
	btn.Start.cmd := FALSE; //Шаг проверки: КПК из ГР // Кнопка "Пуск"
	btn.APK.cmd := FALSE; //Шаг проверки: АПК из ГР под газом // Кнопка "АПК"
	btn.Start.cmd := FALSE; //Шаг проверки: АПК из ГР под газом // Кнопка "Пуск"
	btn.AOss.cmd := FALSE; //Шаг проверки: АОсс из Кольца // Кнопка "АОсс"
	btn.Unlock.cmd := FALSE; //Шаг проверки: АОсс из Кольца // Кнопка "Деблокировка"
	btn.GR.cmd := FALSE; //Шаг проверки: АПК из ГР без газа // Кнопка "ГР"
	btn.APK.cmd := FALSE; //Шаг проверки: АПК из ГР без газа // Кнопка "АПК"
	btn.Start.cmd := FALSE; //Шаг проверки: АПК из ГР без газа // Кнопка "Пуск"
	btn.NOss.cmd := FALSE; //Шаг проверки: НОсс из Кольца // Кнопка "НОсс"
	btn.GR.cmd := FALSE; //Шаг проверки: АПМ из ГР без газа // Кнопка "ГР"
	btn.AObs.cmd := FALSE; //Шаг проверки: АОбс из Магистрали // Кнопка "АОбс"
	btn.Unlock.cmd := FALSE; //Шаг проверки: АОбс из Магистрали // Кнопка "Деблокировка"
	btn.M_K.cmd := FALSE; //Шаг проверки: Переход М-К // Кнопка "Переход М-К"
	cmd_Nst_5000 := FALSE; //Шаг проверки: Повышение Nст до 5000 об/мин
	btn.K_M.cmd := FALSE; //Шаг проверки: Переход К-М // Кнопка "Переход К-М"
	btn.NObs.cmd := FALSE; //Шаг проверки: АОбс из Магистрали // Кнопка "НОбс"
	btn.Bleeding.cmd := FALSE; //Шаг проверки: Стравливание из ГР под газом // Кнопка "Стравливание ЦБК"
	btn.Repair.cmd := FALSE; //Шаг проверки: Переход в Ремонт // Кнопка "Ремонт"
	finish := FALSE; //Завершение
END_IF;

