InterfaceAsPlainText.xhtml:
// _^ - ^ _ // Автоматическая проверка защит // Chekmarev
FUNCTION_BLOCK TAutoCheckShield VAR_IN_OUT start : BOOL; END_VAR VAR step : INT := -1; // Проверяемые защиты ( FALSE - не проверена / не успех, TRUE - проверена ) btn_AOss, btn_AObs, AO_PRU, AO_BA, BEAO, SurgeD, Vs_D_Av, KPV2_wOpen, KPV4_wOpen, KPV15_wOpen, Nst_HH, Ntk_Av_HH, Nst_flt, Tg_inSt_HH, Fire_OD, Tg1_inSTdistort_HH, Tg_inSTflt, nIgnition, Fire_flt, Ntk_nBoost, DGdistort, Pa_out14_HH, BZA_ready_2, BZA_alr, Pm_TK_An, Pm_ST_An, Tm_outD_HH, Chip_outD, Ptg_inDG, Pm_Starter_Av, Pm_Starter_An, dP_F_Pv, Ptg_inTRK_LL, dPmg_LL, Pm_N_An, Zs_Nl, Kr6_OF_start, Causeless_KR1_OF, Causeless_KR2_OF, Causeless_KR6_OF, Causeless_KR10_11 : BOOL;
crsCurrent : POINTER TO Tcrs;
callCMD : BOOL; timer : TON; // Общий таймер wd : TON; // злая собака END_VAR

// _^ - ^ _ // Автоматическая проверка защит // Chekmarev
FUNCTION_BLOCK TAutoCheckShield VAR_IN_OUT start : BOOL; END_VAR VAR step : INT := -1; // Проверяемые защиты ( FALSE - не проверена / не успех, TRUE - проверена ) btn_AOss, btn_AObs, AO_PRU, AO_BA, BEAO, SurgeD, Vs_D_Av, KPV2_wOpen, KPV4_wOpen, KPV15_wOpen, Nst_HH, Ntk_Av_HH, Nst_flt, Tg_inSt_HH, Fire_OD, Tg1_inSTdistort_HH, Tg_inSTflt, nIgnition, Fire_flt, Ntk_nBoost, DGdistort, Pa_out14_HH, BZA_ready_2, BZA_alr, Pm_TK_An, Pm_ST_An, Tm_outD_HH, Chip_outD, Ptg_inDG, Pm_Starter_Av, Pm_Starter_An, dP_F_Pv, Ptg_inTRK_LL, dPmg_LL, Pm_N_An, Zs_Nl, Kr6_OF_start, Causeless_KR1_OF, Causeless_KR2_OF, Causeless_KR6_OF, Causeless_KR10_11 : BOOL;
crsCurrent : POINTER TO Tcrs;
callCMD : BOOL; timer : TON; // Общий таймер wd : TON; // злая собака END_VAR

ST.xhtml:
timer ( IN := ( AOss.break XOR AOss.finish ) AND ( AObs.break XOR AObs.finish ) AND NOT timer.Q, PT := T#5S );
btn.Unlock.cmd 	:= timer.Q;
btn.GR.cmd		:= AOss.break AND aobs.break;
IF mde.GR THEN
	timer ( IN := FALSE );
	step := step + 1;
END_IF
wd ( IN := FALSE );

IF start AND step = -1 THEN
	step := 5;
	start := FALSE;
	ELSE 
		start := FALSE;
END_IF

CASE step OF
	5:		// btn_AOss
		Reset();
		btn_AOss	:= FALSE;
		crsCurrent 	:= ADR ( crs.btn_AOss );
	6:
		APK_start( _time := T#15S, nextStep := step + 4, cmd := btn.AOss.cmd, checkCRS := btn_AOss );

	10:		// btn_AObs
		Reset();
		btn_AObs	:= FALSE;
		crsCurrent	:= ADR ( crs.btn_AObs );
	11:
		APK_start( _time := T#30S, nextStep := step + 4, cmd := btn.AObs.cmd, checkCRS := btn_AObs );

	15:		// AO_PRU
		Reset();
		AO_PRU		:= FALSE;
		crsCurrent	:= ADR ( crs.AO_PRU );
	16:
		APK_start( _time := T#29S, nextStep := step + 4, cmd := callCMD, checkCRS := AO_PRU );
		dipar.AO_PRU_1.sim_value := callCMD;
		dipar.AO_PRU_2.sim_value := callCMD;

	20:
		Reset();
		AO_BA		:= FALSE;
		crsCurrent	:= ADR ( crs.AO_BA );
	21:
		APK_start( _time := T#15S, nextStep := step + 4, cmd := dipar.AO_BA.sim_value, checkCRS := AO_BA );

	25:
		Reset();
		BEAO		:= FALSE;
		crsCurrent	:= ADR ( crs.BEAO );
	26:
		APK_start( _time := T#1S, nextStep := step + 4, cmd := dipar.BEAO.sim_value, checkCRS := BEAO );

	30:
		step := 31;
	31:
		step := step + 4;

	35:
		Reset();
		SurgeD		:= FALSE;
		crsCurrent	:= ADR ( crs.SurgeD );
	36:
		APK_start( _time := T#15S, nextStep := step + 4, cmd := dipar.SurgeD.sim_value, checkCRS := SurgeD );

	40:
		Reset();
		Vs_D_Av		:= FALSE;
		crsCurrent	:= ADR ( crs.Vs_D_Av );
	41:
		APK_start( _time := T#15S, nextStep := step + 4, cmd := dipar.Vs_D_Av.sim_value, checkCRS := Vs_D_Av );

	45:
		Reset();
		KPV2_wOpen:= FALSE;
		crsCurrent	:= ADR ( crs.KPV234_wOpen );
	46:
		APK_heat( _time := T#15S, nextStep := step + 4, cmd := callCMD, checkCRS := KPV2_wOpen );
		IF callCMD THEN
			dipar.KPV2_off.sim_value := FALSE;
		END_IF

	50: step := 51;		// KPV3
	51: step := 55;

	55: Reset();
		KPV4_wOpen	:= FALSE;
		crsCurrent	:= ADR ( crs.KPV234_wOpen );
	56: 
		APK_heat( _time := T#1M, nextStep := step + 4, cmd := callCMD, checkCRS := KPV4_wOpen );
		IF callCMD THEN
			dipar.KPV4_off.sim_value := FALSE;
		END_IF

	60:
		Reset();
		KPV15_wOpen	:= FALSE;
		crsCurrent	:= ADR ( crs.KPV15_wOpen );
	61:
		APK_work( _time := T#25S, nextStep := step + 4, cmd := callCMD, checkCRS := KPV15_wOpen );
		IF callCMD THEN
			dipar.KPV5_off.sim_value := FALSE;
		END_IF

	65:
		Reset();
		Nst_HH		:= FALSE;
		crsCurrent	:= ADR ( crs.Nst_HH );
	66:
		APK_start( _time := T#15S, nextStep := step + 4, cmd := callCMD, checkCRS := Nst_HH );
		acpar.Nst.sim_value := 9301 * TO_BYTE ( callCMD );
		acpar.Nst.sim_on	:= callCMD;

	70:
		Reset();
		Ntk_Av_HH	:= FALSE;
		crsCurrent	:= ADR ( crs.Ntk_Av_HH );
	71:
		APK_start( _time := T#15S, nextStep := step + 4, cmd := callCMD, checkCRS := Ntk_Av_HH );
		acpar.Ntk.sim_value := 8401 * TO_BYTE ( callCMD );	// aipar переписывается в ТР
		acpar.Ntk.sim_on	:= callCMD;		

	75:
		Reset();
		Nst_flt		:= FALSE;
		crsCurrent	:= ADR ( crs.Nst_flt );
	76:
		APK_start(_time := T#20S, nextStep := step + 4, cmd := callCMD, checkCRS := Nst_flt );
		aipar.Nst_1.flt_test	:= callCMD;
		aipar.Nst_2.flt_test	:= callCMD;

	80:
		Reset();
		Tg_inSt_HH	:= FALSE;
		crsCurrent	:= ADR ( crs.Tg_inST_HH );
	81:
		APK_start( _time := T#15S, nextStep := step + 4, cmd := callCMD, checkCRS := Tg_inSt_HH );
		acpar.Tg_inST.sim_value	:= 671 * TO_BYTE ( callCMD );
		acpar.Tg_inST.sim_on	:= callCMD;

	85:
		Reset();
		Fire_OD		:= FALSE;
		crsCurrent	:= ADR ( crs.Fire_OD );
	86:
		APK_start( _time := T#1S, nextStep := step + 4, cmd := dipar.Fire_OD.sim_value, checkCRS := Fire_OD );

	90:
		Reset();
		Tg1_inSTdistort_HH	:= FALSE;
		crsCurrent			:= ADR ( crs.Tg1_inSTdistort_HH );
	91:
		APK_heat(_time := T#30S, nextStep := step + 4, cmd := callCMD, checkCRS := Tg1_inSTdistort_HH );
		aipar.Tg_inST_1.sim_value := acpar.Tg_inST.value + 150 * TO_BYTE ( callCMD );

	95:
		Reset();
		Tg_inSTflt	:= FALSE;
		crsCurrent	:= ADR ( crs.Tg_inSTflt );
	96:
		APK_start( _time := T#10S, nextStep := step + 4, cmd := callCMD, checkCRS := Tg_inSTflt );
		aipar.Tg_inST_1.flt_test := callCMD;
		aipar.Tg_inST_3.flt_test := callCMD;
		aipar.Tg_inST_5.flt_test := callCMD;
		aipar.Tg_inST_6.flt_test := callCMD;

	100:
		Reset();
		nIgnition	:= FALSE;
		crsCurrent	:= ADR ( crs.nIgnition );		
	101:
		APK_start(_time := T#10S, nextStep := step + 4, cmd := callCMD, checkCRS := nIgnition );
		IF am.AZ.on AND callCMD THEN
			am.SK.on := FALSE;
		END_IF

	105:
		Reset();
		Fire_flt	:= FALSE;
		crsCurrent	:= ADR ( crs.Fire_flt );
	106:
		APK_work( _time := T#21S, nextStep := step + 4, cmd := callCMD, checkCRS := Fire_flt );
		crs.Tg1_inSTdistort_HH.alg_check := callCMD;
		crs.Tg2_inSTdistort_HH.alg_check := callCMD;
		crs.Tg3_inSTdistort_HH.alg_check := callCMD;
		crs.Tg4_inSTdistort_HH.alg_check := callCMD;
		crs.Tg5_inSTdistort_HH.alg_check := callCMD;
		crs.Tg6_inSTdistort_HH.alg_check := callCMD;
		acpar.Tg_inST.sim_on := callCMD;
		IF callCMD THEN
			acpar.Tg_inST.sim_value := acpar.Tg_inST.value - 10.0;
		END_IF

	110:
		Reset();
		Ntk_nBoost	:= FALSE;
		crsCurrent	:= ADR ( crs.Ntk_nBoost );
	111:
		APK_start( _time := T#30S, nextStep := step + 4, cmd := callCMD, checkCRS := Ntk_nBoost );
		acpar.Ntk.sim_on := callCMD AND aipar.Ntk_1.value > 5500;
		acpar.Nst.sim_on := callCMD AND aipar.Nst_1.value > 9100;
		acpar.Ntk.sim_value := 5500;
		acpar.Nst.sim_value := 9000;

	115:
		Reset();
		DGdistort	:= FALSE;
		crsCurrent	:= ADR ( crs.DGdistort );
	116:
		APK_heat( _time := T#10S, nextStep := step + 4, cmd := callCMD, checkCRS := DGdistort );
		aipar.DG_pos.sim_value := aopar.DG_set.value + 2 * TO_BYTE ( callCMD );

	120:
		Reset();
		Pa_out14_HH	:= FALSE;
		crsCurrent	:= ADR ( crs.Pa_out14_HH );
	121:
		APK_heat( _time := T#15S, nextStep := step + 4, cmd := callCMD, checkCRS := Pa_out14_HH );
		aipar.Pa_out14.sim_value := 2.1 * TO_BYTE ( callCMD );

	125:
		Reset();
		BZA_ready_2	:= FALSE;
		crsCurrent	:= ADR ( crs.BZA_ready_2 );
	126:
		APK_start( _time := T#1S, nextStep := step + 4, cmd := callCMD, checkCRS := BZA_ready_2 );
		IF callCMD THEN
			dipar.BZA_ready_2.sim_value := NOT callCMD;
		END_IF		

	130:
		Reset();
		BZA_alr		:= FALSE;
		crsCurrent	:= ADR ( crs.BZA_alr );
	131:
		APK_start( _time := T#45S, nextStep := step + 4, cmd := dipar.BZA_alr.sim_value, checkCRS := BZA_alr );

	135:
		Reset();
		Pm_TK_An	:= FALSE;
		crsCurrent	:= ADR ( crs.Pm_TK_An );
	136:
		APK_start( _time := T#1M, nextStep := step + 4, cmd := dipar.Pm_TK_An.sim_value, checkCRS := Pm_TK_An );

	140:
		Reset();
		Pm_ST_An	:= FALSE;
		crsCurrent	:= ADR ( crs.Pm_ST_An );
	141:
		APK_start( _time := T#70S, nextStep := step + 4, cmd := dipar.Pm_ST_An.sim_value, checkCRS := Pm_ST_An );

	145:
		Reset();
		Tm_outD_HH	:= FALSE;
		crsCurrent	:= ADR ( crs.Tm_outD_HH );
	146:
		APK_heat( _time := T#10S, nextStep := step + 4, cmd := callCMD, checkCRS := Tm_outD_HH );
		aipar.Tm_outD.sim_value	:= 86 * TO_BYTE ( callCMD );

	150:
		Reset();
		Chip_outD	:= FALSE;
		crsCurrent	:= ADR ( crs.Chip_outD );
	151:
		APK_start( _time := T#11S, nextStep := step + 4, cmd := dipar.Chip_outD.sim_value, checkCRS := Chip_outD );

	155:
		Reset();
		Ptg_inDG	:= FALSE;
		crsCurrent	:= ADR ( crs.Ptg_inDG_An );
	156:
		APK_start( _time := T#1M, nextStep := step + 4, cmd := dipar.Ptg_inDG_An.sim_value, checkCRS := Ptg_inDG );

	160:
		Reset();
		Pm_Starter_Av	:= FALSE;
		crsCurrent		:= ADR ( crs.Pm_Starter_Av );
	161:
		APK_start( _time := T#1M, nextStep := step + 4, cmd := callCMD, checkCRS := Pm_Starter_Av );
		dipar.Pm_Starter_Av.sim_value := callCMD;

	165:
		Reset();
		Pm_Starter_An	:= FALSE;
		crsCurrent		:= ADR ( crs.Pm_Starter_An );
	166:
		HP( _time := T#70S, nextStep := step + 4, cmd := callCMD, checkCRS := Pm_Starter_An );
		dipar.Pm_Starter_An.sim_value := callCMD;

	170:
		Reset();
		dP_F_Pv		:= FALSE;
		crsCurrent	:= ADR ( crs.dP_F_Pv );
	171:
		APK_start( _time := T#15S, nextStep := step + 4, cmd := dipar.dP_F_Pv.sim_value, checkCRS := dP_F_Pv );

	175:
		Reset();
		Ptg_inTRK_LL:= FALSE;
		crsCurrent	:= ADR ( crs.Ptg_inTRK_LL );
	176:
		APK_heat( _time := T#15S, nextStep := step + 4, cmd := callCMD, checkCRS := Ptg_inTRK_LL );
		IF callCMD THEN
			aipar.Ptg_inTRK.sim_value := 0.9;
		END_IF

	180:
		step := 181;
	181:
		step := step + 4;

	185:
		Reset();
		dPmg_LL		:= FALSE;
		crsCurrent	:= ADR ( crs.dPmg_LL );
	186:
		APK_start( _time := T#1M, nextStep := step + 4, cmd := callCMD, checkCRS := dPmg_LL );
		IF callCMD AND aipar.dPmg.value > 0.71 THEN
			aipar.dPmg.sim_value := 0.2;
		END_IF

	190:
		Reset();
		Pm_N_An		:= FALSE;
		crsCurrent	:= ADR ( crs.Pm_N_An );
	191:
		APK_start( _time := T#1M, nextStep := step + 4, cmd := dipar.Pm_N_An.sim_value, checkCRS := Pm_N_An );

	195:
		Reset();
		Zs_Nl		:= FALSE;
		crsCurrent	:= ADR ( crs.Zs_Nl );
	196:
		APK_start( _time := T#1M, nextStep := step + 4, cmd := dipar.Zs_Nl.sim_value, checkCRS := Zs_Nl );

	200:
		step := 201;
	201:
		step := step + 4;

	205:
		Reset();
		Kr6_OF_start	:= FALSE;
		crsCurrent		:= ADR ( crs.Kr6_off_start );
	206:
		APK_heat( _time := T#2M, nextStep := step + 4, cmd := callCMD, checkCRS := Kr6_OF_start );
		IF acpar.Nst.value > 300 THEN
			dipar.Kr6_off.sim_value := TRUE;
		END_IF

	210:
		Reset();
		Causeless_KR1_OF:= FALSE;
		crsCurrent		:= ADR ( crs.Causeless_KR1_off );
	211:
		APK_work( _time := T#1M, nextStep := step + 4, cmd := callCMD, checkCRS := Causeless_KR1_OF );
		IF callCMD THEN
			dipar.Kr1_ON.sim_value := NOT callCMD;
		END_IF

	215:
		Reset();
		Causeless_KR2_OF:= FALSE;
		crsCurrent		:= ADR ( crs.Causeless_KR2_off );
	216:
		APK_work( _time := T#1M, nextStep := step + 4, cmd := callCMD, checkCRS := Causeless_KR2_OF );
		IF callCMD THEN
			dipar.Kr2_ON.sim_value := NOT callCMD;
			dipar.Kr6_off.sim_value := callCMD;
		END_IF

	220:
		Reset();
		Causeless_KR6_OF := FALSE;
		crsCurrent		:= ADR ( crs.Causeless_KR6_off );
	221: 
		APK_work( _time := T#1M, nextStep := step + 4, cmd := callCMD, checkCRS := Causeless_KR6_OF );
		IF callCMD THEN
			dipar.Kr2_off.sim_value := callCMD;
			dipar.Kr6_ON.sim_value := NOT callCMD;
		END_IF

	225:
		Reset();
		Causeless_KR10_11:= FALSE;
		crsCurrent		:= ADR( crs.Causeless_KR10_11 );
	226:
		APK_start( _time := T#5M, nextStep := step + 4, cmd := callCMD, checkCRS := Causeless_KR10_11 );
		IF am.Kr15.on THEN
			dipar.Kr10_off.sim_value := FALSE;
		END_IF

	230:
		step := -1;

END_CASE

timer();

InterfaceAsPlainText.xhtml:
METHOD PRIVATE APK_start : BOOL
VAR_INPUT
	_time	: TIME;
	nextStep: INT;
END_VAR
VAR_IN_OUT
	cmd		: BOOL;
	checkCRS: BOOL;
END_VAR

METHOD PRIVATE APK_start : BOOL
VAR_INPUT
	_time	: TIME;
	nextStep: INT;
END_VAR
VAR_IN_OUT
	cmd		: BOOL;
	checkCRS: BOOL;
END_VAR

ST.xhtml:
IF mde.GR THEN
	timer (IN := TRUE, PT := T#5S);
	btn.APK.cmd := timer.Q;
END_IF
IF tch.ReadyAPK.value THEN
	timer ( IN := FALSE );
	btn.Unlock.cmd 	:= TRUE;
	btn.Start.cmd	:= TRUE;
END_IF
IF mde.APK THEN
	timer (IN := TRUE, PT := _time);
	cmd := timer.Q;
END_IF		
IF crsCurrent^.out THEN
	timer (IN 	:= FALSE);
	checkCRS 	:= TRUE;
	cmd			:= FALSE;
	step := nextStep;
	wd ( IN := FALSE );
END_IF

wd ( IN := TRUE, PT := T#5M + _time );
IF wd.Q THEN
	btn.AObs.cmd := TRUE;
	step 	:= nextStep;
	cmd		:= FALSE;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PRIVATE APK_start : BOOL
VAR_INPUT
	_time	: TIME;
	nextStep: INT;
END_VAR
VAR_IN_OUT
	cmd		: BOOL;
	checkCRS: BOOL;
END_VAR

METHOD PRIVATE APK_heat : BOOL
VAR_INPUT
	_time	: TIME;
	nextStep: INT;
