InterfaceAsPlainText.xhtml:
{region INFO}
(*
 Назначение:   Ручной вызов обработчиков дискретных ИМов в base цикле
 Автор:        /chekmarev/ 17.04.2025
 Проект:       KA107
*)
{endregion}
FUNCTION am_update_base : BOOL
VAR
	KPV15du	: BOOL;
	KPV15on	: BOOL;
	KPV15off: BOOL;
	KPV23du	: BOOL;
	KPV23on	: BOOL;
	KPV23off: BOOL;
END_VAR

ST.xhtml:
// ---------- блок самоподхвата ДУ у КПВ2 и КПВ3 по изменению одного из них с HMI
KPV23du	:= am.KPV2.cmd.0 OR am.KPV3.cmd.0;	// делаем так, чтобы не плодить глобальные переменные
KPV23on := am.KPV2.cmd.1 OR am.KPV3.cmd.1;
KPV23off := am.KPV2.cmd.2 OR am.KPV3.cmd.2;

engine.KPV2du( in	:= am.KPV2.cmd.0 );		// к этому моменту OPC сервер должен внести изменения в бит, если есть воздействие с HMI
engine.KPV2on( in	:= am.KPV2.cmd.1 );
engine.KPV2off( in	:= am.KPV2.cmd.2 );
engine.KPV3du( in	:= am.KPV3.cmd.0 );
engine.KPV3on( in	:= am.KPV3.cmd.1 );
engine.KPV3off( in	:= am.KPV3.cmd.2 );

IF engine.KPV2du.Qf OR engine.KPV3du.Qf THEN
	KPV23du := TRUE;
END_IF
IF engine.KPV2on.Qf OR engine.KPV3on.Qf THEN
	KPV23on := TRUE;
END_IF
IF engine.KPV2off.Qf OR engine.KPV3off.Qf THEN
	KPV23off := TRUE;
END_IF
IF engine.KPV2du.Qr OR engine.KPV3du.Qr THEN
	KPV23du	:= FALSE;
END_IF
IF engine.KPV2on.Qr OR engine.KPV3on.Qr THEN
	KPV23on := FALSE;
END_IF
IF engine.KPV2off.Qr OR engine.KPV3off.Qr THEN
	KPV23off := FALSE;
END_IF

// ---------- блок самоподхвата ДУ у КПВ1 и КПВ5 по изменению одного из них с HMI
KPV15du	:= am.KPV1.cmd.0 OR am.KPV5.cmd.0;
KPV15on	:= am.KPV1.cmd.1 OR am.KPV5.cmd.1;
KPV15off:= am.KPV1.cmd.2 OR am.KPV5.cmd.2;

engine.KPV1du( in	:= am.KPV1.cmd.0 );
engine.KPV1on( in	:= am.KPV1.cmd.1 );
engine.KPV1off( in	:= am.KPV1.cmd.2 );
engine.KPV5du( in	:= am.KPV5.cmd.0 );
engine.KPV5on( in	:= am.KPV5.cmd.1 );
engine.KPV5off( in	:= am.KPV5.cmd.2 );

IF engine.KPV1du.Qf OR engine.KPV5du.Qf THEN
	KPV15du := TRUE;
END_IF
IF engine.KPV1on.Qf OR engine.KPV5on.Qf THEN
	KPV15on := TRUE;
END_IF
IF engine.KPV1off.Qf OR engine.KPV5off.Qf THEN
	KPV15off := TRUE;
END_IF
IF engine.KPV1du.Qr OR engine.KPV5du.Qr THEN
	KPV15du	:= FALSE;
END_IF
IF engine.KPV1on.Qr OR engine.KPV5on.Qr THEN
	KPV15on := TRUE;
END_IF
IF engine.KPV1off.Qr OR engine.KPV5off.Qr THEN
	KPV15off := TRUE;
END_IF
// -----------------------------------

//КПВ 1
//Тип: 1x2
am.KPV1.cmd.0 	:= KPV15du;
am.KPV1.cmd.1 	:= KPV15on;
am.KPV1.cmd.2 	:= KPV15off;
am.KPV1(
	DU_prm := alg.V_000,
	onSigFlt := dipar.KPV1_ON.flt,
	onSig := dipar.KPV1_ON.value,
	onSig_sim_on := dipar.KPV1_ON.sim_on,
	onSig_sim_value := dipar.KPV1_ON.sim_value,
	offSigFlt := dipar.KPV1_off.flt,
	offSig := dipar.KPV1_off.value,
	offSig_sim_on := dipar.KPV1_off.sim_on,
	offSig_sim_value := dipar.KPV1_off.sim_value,
	onFlt := dopar.KPV15_ON.flt);
// dopar.KPV15_ON.value	-> Вызов в am_update_fast()	
//--------------------------------------------------------------------------

//КПВ 2
//Тип: 1x2
am.KPV2.cmd.0	:= KPV23du;
am.KPV2.cmd.1	:= KPV23on;
am.KPV2.cmd.2	:= KPV23off;
am.KPV2(
	DU_prm := alg.V_000,
	onSigFlt := dipar.KPV2_ON.flt,
	onSig := dipar.KPV2_ON.value,
	onSig_sim_on := dipar.KPV2_ON.sim_on,
	onSig_sim_value := dipar.KPV2_ON.sim_value,
	offSigFlt := dipar.KPV2_off.flt,
	offSig := dipar.KPV2_off.value,
	offSig_sim_on := dipar.KPV2_off.sim_on,
	offSig_sim_value := dipar.KPV2_off.sim_value,
	onFlt := dopar.KPV23_OFF.flt);
//--------------------------------------------------------------------------

//КПВ 3
//Тип: 1x2
am.KPV3.cmd.0	:= KPV23du;
am.KPV3.cmd.1	:= KPV23on;
am.KPV3.cmd.2	:= KPV23off;
am.KPV3(
	DU_prm := alg.V_000,
	onSigFlt := dipar.KPV3_ON.flt,
	onSig := dipar.KPV3_ON.value,
	onSig_sim_on := dipar.KPV3_ON.sim_on,
	onSig_sim_value := dipar.KPV3_ON.sim_value,
	offSigFlt := dipar.KPV3_off.flt,
	offSig := dipar.KPV3_off.value,
	offSig_sim_on := dipar.KPV3_off.sim_on,
	offSig_sim_value := dipar.KPV3_off.sim_value,
	onFlt := dopar.KPV23_OFF.flt);
dopar.KPV23_OFF.value := NOT am.KPV2.onOUT OR NOT am.KPV3.onOut;
//--------------------------------------------------------------------------

// КПВ4
// Штатный вызов (создан конфигуратором)

//КПВ 5
//Тип: 1x2
am.KPV5.cmd.0 := KPV15du;
am.KPV5.cmd.1 := KPV15on;
am.KPV5.cmd.2 := KPV15off;
am.KPV5(
	DU_prm := alg.V_000,
	onSigFlt := dipar.KPV5_ON.flt,
	onSig := dipar.KPV5_ON.value,
	onSig_sim_on := dipar.KPV5_ON.sim_on,
	onSig_sim_value := dipar.KPV5_ON.sim_value,
	offSigFlt := dipar.KPV5_off.flt,
	offSig := dipar.KPV5_off.value,
	offSig_sim_on := dipar.KPV5_off.sim_on,
	offSig_sim_value := dipar.KPV5_off.sim_value,
	onFlt := dopar.KPV15_ON.flt);
// dopar.KPV15_ON.value	-> Вызов в am_update_fast()
//--------------------------------------------------------------------------

//Кран 9
//Тип: 2x2
am.Kr9(
	DU_prm := FALSE,
	onSigFlt := dipar.Kr9_ON.flt,
	onSig := dipar.Kr9_ON.value,
	onSig_sim_on := dipar.Kr9_ON.sim_on,
	onSig_sim_value := dipar.Kr9_ON.sim_value,
	offSigFlt := dipar.Kr9_off.flt,
	offSig := dipar.Kr9_off.value,
	offSig_sim_on := dipar.Kr9_off.sim_on,
	offSig_sim_value := dipar.Kr9_off.sim_value,
	onFlt := dopar.Kr12_ON.flt,
	offFlt := dopar.KR12_OFF.flt);

//Кран 10
//Тип: 2x2
am.Kr10(
	DU_prm := FALSE,
	onSigFlt := dipar.Kr10_ON.flt,
	onSig := dipar.Kr10_ON.value,
	onSig_sim_on := dipar.Kr10_ON.sim_on,
	onSig_sim_value := dipar.Kr10_ON.sim_value,
	offSigFlt := dipar.Kr10_off.flt,
	offSig := dipar.Kr10_off.value,
	offSig_sim_on := dipar.Kr10_off.sim_on,
	offSig_sim_value := dipar.Kr10_off.sim_value,
	onFlt := dopar.Kr11_ON.flt,
	offFlt := dopar.Kr11_OFF.flt);

// ---------- блок самоподхвата ДУ у КПВ2 и КПВ3 по изменению одного из них с HMI
// выходы триггера сброшены, запоминаем текущее значение
engine.KPV2du( in	:= am.KPV2.cmd.0 );
engine.KPV2on( in	:= am.KPV2.cmd.1 );
engine.KPV2off( in	:= am.KPV2.cmd.2 );
engine.KPV3du( in	:= am.KPV3.cmd.0 );
engine.KPV3on( in	:= am.KPV3.cmd.1 );
engine.KPV3off( in	:= am.KPV3.cmd.2 );
// ------------------------------------
// ---------- блок самоподхвата ДУ у КПВ1 и КПВ5 по изменению одного из них с HMI
engine.KPV1du( in	:= am.KPV1.cmd.0 );
engine.KPV1on( in	:= am.KPV1.cmd.1 );
engine.KPV1off( in	:= am.KPV1.cmd.2 );
engine.KPV5du( in	:= am.KPV5.cmd.0 );
engine.KPV5on( in	:= am.KPV5.cmd.1 );
engine.KPV5off( in	:= am.KPV5.cmd.2 );
// -----------------------------------

InterfaceAsPlainText.xhtml:
{region INFO}
(*
 Назначение:   Ручной вызов обработчиков дискретных ИМов в base цикле
 Автор:        /chekmarev/ 17.04.2025
 Проект:       KA107
