END_VAR

ST.xhtml:
s_tunpar.ASprot.Pin.value	:= aipar.Pg_inN.value; 
s_tunpar.ASprot.Pout.value	:= aipar.Pg_outN.value; 
s_tunpar.ASprot.Tin.value	:= aipar.Tg_inN.value;  
s_tunpar.ASprot.Tout.value	:= aipar.Tg_outN.value; 
s_tunpar.ASprot.dPconf.value:= aipar.dP_conf.value; 
s_tunpar.ASprot.Nst.value	:= acpar.Nst.value; 
s_tunpar.ASprot.Patm.value	:= 101.6; 

s_tunpar.ASprot.Pin.flt		:= aipar.Pg_inN.flt; 
s_tunpar.ASprot.Pout.flt	:= aipar.Pg_outN.flt; 
s_tunpar.ASprot.Tin.flt		:= aipar.Tg_inN.flt;  
s_tunpar.ASprot.Tout.flt	:= aipar.Tg_outN.flt; 
s_tunpar.ASprot.dPconf.flt	:= TRUE; //aipar.dP_conf.flt; 
s_tunpar.ASprot.Nst.flt		:= acpar.Nst.flt; 

s_tunpar_update();

s_tunpar.ASprot(
	cycle			:= cycle_time_fast, 
	D				:= 0.5917, // относительная плотность газа по воздуху - обычно выход блока расчета газовых констант, для упрощенного проекта задана постоянная
	mu				:= 17.091, // молярная масса газа, кг/кмоль - обычно выход блока расчета газовых констант, для упрощенного проекта задана постоянная
	sigDKS			:= FALSE, // при TRUE сигнал 
	sigPreSurgeOR	:= TRUE, // при TRUE сигнал предпомпажа (защиты) формируется при падении dPk ИЛИ росте Nst, при FALSE при падении dPk И росте Nst, проверить в работе
	protectOn		:= mde.M, // Взведение помпажной защиты. Магистраль? Переход К->М?
	sigCheck		:= mde.PZ, // Проверка защит 
	reset			:= btn.Unlock.out, // Деблокировка 
	calcSRon		:= TRUE,
	sigDKS 			:= TRUE,
	initSecResToMain := 3.0,
 	prod        => s_aspar.prod.value,  // объемная производительность, м3/с
 	prodCom     => s_aspar.prodCom.value, // коммерческая производительность, млн·нм3/сут
  	Qc          => s_aspar.Qc.value, // коммерческая производительность, нм3/ч
  	pressRatio  => s_aspar.pressRatio.value,
  	NstNorm     => s_aspar.NstNorm.value,
 // 	antisurgeBrk=> ,
 // 	mainContBrk => ,
 // 	res1ContBrk => ,
 // 	res2ContBrk => ,
  	surgeRes    => s_aspar.surgeRes.value,
  	ddPconf     => s_aspar.ddPconf.value, // производная перепада давления на конфузоре нагнетателя по времени
  	dNst        => s_aspar.dNst.value, // производная частоты вращения ротора нагнетателя по времени
  	preSurge    => tch.AS_preSurge.value, // сигнал "Предпомпажное состояние"
 	surge       => tch.AS_surge.value, // сигнал "Помпаж нагнетателя"
 // 	surgeAlertBrk=> , // сигнал "Отказ сигнализатора помпажа"
  	surgeSign_ddPconf=> tch.AS_surgeSign_ddPconf.value, // внутренний сигнал "Предпомпажное состояние" по падению dP на конфузоре //Dergaev 2024-11-02
  	surgeSign_dNst	=> tch.AS_surgeSign_dNst.value // внутренний сигнал "Предпомпажное состояние" по росту частоты вращения  //Dergaev 2024-11-02

//	emergOpenBypass=> Команда на 6 (вход в обработчик ИМ) - см. ALG_GO_AM

   );

 s_tunpar.ASprot.update();

