FUNCTION_BLOCK TASProtector VAR_INPUT // время цикла cycle : REAL;
// входные аналоговые параметры Pin : Taspar; // P газа на входе ЦБК, МПа Pout : Taspar; // P газа на выходе ЦБК, МПа Tin : Taspar; // T газа на входе ЦБК, °С Tout : Taspar; // T газа на выходе ЦБК, °С dPconf : Taspar; // перепад давления на конфузоре, кПа Nst : Taspar; // Частота вращения СТ, об/мин Patm : Taspar; // атмосферное давление, кПа
D : REAL; // относительная плотность газа по воздуху mu : REAL; // молярная масса газа, кг/кмоль
