// вычислить помпажный запас resCalc(cycle := cycle, Nst := Nst.value, Pin := Pin.value, Pout := Pout.value, Tin := Tin.value, dPconf := dPconf.value, Patm := Patm.value, NstBrk := Nst.flt, PinBrk := Pin.flt, PoutBrk := Pout.flt, dPconfBrk := dPconf.flt, c2Main := s_tunpar.c2Main.value, c1Main := s_tunpar.c1Main.value, c0Main := s_tunpar.c0Main.value, c21Res := s_tunpar.c2Res1.value, c11Res := s_tunpar.c1Res1.value, c01Res := s_tunpar.c0Res1.value, c22Res := s_tunpar.c2Res2.value, c12Res := s_tunpar.c1Res2.value, c02Res := s_tunpar.c0Res2.value, kConf := s_tunpar.Kconf.value, nNorm := s_tunpar.nNorm.value, D := D, mu := mu, check := sigCheck, initSecResToMain := initSecResToMain, NstNorm=>NstNorm , antisurgeBrk=>antisurgeBrk , mainContBrk=>mainContBrk , res1ContBrk=>res1ContBrk , res2ContBrk=>res2ContBrk );
IF protectOn THEN prod:=resCalc.prod; prodCom:=resCalc.prodCom; Qc:=resCalc.Qc; pressRatio:=resCalc.pressRatio; surgeRes:=resCalc.surgeRes; ELSE prod:=0.0; prodCom:=0.0; Qc:=0.0; pressRatio:=1.0; surgeRes:=100.0; END_IF; // обновить сигнализатор помпажа surgeAlert( dPconf := dPconf.value, Nst := Nst.value, dPconfBrk := dPconf.flt, NstBrk := Nst.flt, maxRateDPconf := s_tunpar.maxRateDPconf.value, maxRateNst := s_tunpar.maxRateNst.value, SAoffDelay := s_tunpar.SAoffDelay.value, SAdelay := s_tunpar.SAdelay.value, blockDelay := s_tunpar.blockDelay.value, resetDelay := s_tunpar.resetDelay.value, cycle := cycle, permit := protectOn, alternate := sigDKS, preSurgeOR := sigPreSurgeOR, init := init, check := sigCheck, ddPconf=>ddPconf , dNst=>dNst , preSurge=>preSurge , surge=>surge , surgeAlertBrk=>surgeAlertBrk , surgeSign_ddPconf=>surgeSign_ddPconf , surgeSign_dNst=>surgeSign_dNst );
IF init THEN init := FALSE; END_IF;
// принудительное открытие байпаса emergOpenBypass := protectOn AND NOT check AND ( surgeAlert.preSurge OR surgeAlert.surge OR calcSRon AND ( resCalc.surgeRes < s_tunpar.minSR.value ) OR emergOpenBypass ) AND NOT reset;

