// Класс, обслуживающий наработку агрегата, а также подсчёт пуско-остановов
// Chekmarev
{attribute 'symbol' := 'none'}
FUNCTION_BLOCK TMotoClockHandler
VAR_INPUT
	start		: BOOL;		// сигнал пуска агрегата
	stop		: BOOL;		// сигнал останова двигателя
	NO			: BOOL;		// сигнал НО
	AO			: BOOL;		// сигнал АО
	work		: BOOL;		// агрегат в работе
	reserve		: BOOL;		// агрегат в резерве/ремонте
	gaz			: BOOL;		// газ в контуре
	path		: STRING := 'OpTime/engine/count.txt';	// путь до файла
END_VAR
VAR
	Qstart			: TEdgeDetect;
	Qno				: TEdgeDetect;
	Qao				: TEdgeDetect;

	// экземпляр ФБ для работы с файлом счётчиков пусков/остановов
	countFile	: FileManager;
	// ошибка работы с файлом
	err			: INT;
	init		: BOOL;
	// признак необходимости записи значений в файл
	xWrite		: BOOL;
	// признак пуска двигателя
	isStarted	: BOOL;
	// прежнее время
	oldTime		: UDINT;
	// временные переменные для хранения наработок
	generalOpTimeTemp,
	generalOpTimeOld,
	workOpTimeTemp,
	workOpTimeOld	: REAL;
END_VAR
VAR_IN_OUT
	// количество пусков
	countStart	: Ttunpar;
	// количество НО
	countNO		: Ttunpar;
	// количество АО
	countAO		: Ttunpar;

	// общая наработка в часах
	generalOpTime: Ttunpar;
	// наработка на режиме в часах
	workOpTime	: Ttunpar;
END_VAR
VAR CONSTANT
	rn	: STRING := '$R$N';
END_VAR

