	start		: BOOL;		// сигнал пуска агрегата
	stop		: BOOL;		// сигнал останова двигателя
	NO			: BOOL;		// сигнал НО
	AO			: BOOL;		// сигнал АО
	work		: BOOL;		// агрегат в работе
	reserve		: BOOL;		// агрегат в резерве/ремонте
	gaz			: BOOL;		// газ в контуре
	path		: STRING := 'OpTime/engine/count.txt';	// путь до файла
END_VAR
VAR
	Qstart			: TEdgeDetect;
	Qno				: TEdgeDetect;
	Qao				: TEdgeDetect;

	// экземпляр ФБ для работы с файлом счётчиков пусков/остановов
	countFile	: FileManager;
	// ошибка работы с файлом
	err			: INT;
	init		: BOOL;
	// признак необходимости записи значений в файл
	xWrite		: BOOL;
