ST.xhtml:
Qstart( in := start );
Qno( in := NO );
Qao( in := AO );

IF Qstart.Qf THEN
	countStart.value := countStart.value + 1;
	xWrite := TRUE;
END_IF

IF Qno.Qr AND NOT AO THEN
	countNO.value	:= countNO.value + 1;
	xWrite := TRUE;
END_IF

IF Qao.Qf AND ( NOT reserve OR gaz ) THEN
	countAO.value	:= countAO.value + 1;
	xWrite := TRUE;
END_IF

IF NOT init THEN
	countFile.FileName := path;
	init := Read();
END_IF

IF xWrite THEN
	xWrite := NOT Write();
END_IF

countFile.Update();

isStarted := ( start OR isStarted ) AND NOT stop;
xWrite := OpTime();

IF NOT countfile.xBusy THEN
	temp := CONCAT( TO_STRING( countStart.value ), rn );
	temp := CONCAT( temp, TO_STRING( countNO.value ));
	temp := CONCAT( temp, rn );
	temp := CONCAT( temp, TO_STRING( countAO.value ));
	temp := CONCAT( temp, rn );
	temp := CONCAT( temp, TO_STRING( generalOpTime.value ));
	temp := CONCAT( temp, rn );
	temp := CONCAT( temp, TO_STRING( workOpTime.value ));

	countFile.Record := temp;
END_IF

IF countFile.WDone THEN
	Write := TRUE;
END_IF

IF countFile.xError THEN
	err := countFile.eError;
	Write := TRUE;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PRIVATE Read : BOOL
VAR
	temp	: STRING;
	sstart,
	sNO,
	sAO,
	sGeneral,
	sWork	: STRING;

	pos		: INT;
	l		: INT;
END_VAR

ST.xhtml:
temp := countFile.Record;

IF countFile.RDone THEN
	pos		:= FIND( temp, rn ) - 1;
	sstart 	:= LEFT( temp, pos );
	pos 	:= pos + LEN( rn );
	temp	:= RIGHT( temp, LEN( temp ) - pos );
	pos 	:= FIND( temp , rn )- 1;
	sNO		:= LEFT( temp, pos );
	pos		:= pos + LEN( rn );
	temp	:= RIGHT( temp, LEN( temp ) - pos );
	pos		:= FIND( temp, rn ) - 1;
	sAO		:= LEFT( temp, pos );
	pos		:= pos + LEN( rn );
	temp	:= RIGHT( temp, LEN( temp ) - pos );
	pos		:= FIND( temp, rn ) - 1;
	sGeneral:= LEFT(temp, pos );
	pos		:= pos + LEN( rn );
	temp	:= RIGHT( temp, LEN( temp ) - pos );
	pos		:= FIND( temp, rn ) - 1;
	IF pos = -1 THEN
		pos := LEN( temp );
	END_IF
	sWork	:= LEFT(temp, pos );

	countStart.value	:= TO_REAL( sstart );
	countNO.value		:= TO_REAL( sNO );
	countAO.value		:= TO_REAL( sAO );

	generalOpTime.value	:= TO_REAL( sGeneral );
	workOpTime.value	:= TO_REAL( sWork );

	Read	:= TRUE;
END_IF

IF countFile.xError THEN
	err		:= countFile.eError;
	Read	:= TRUE;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PRIVATE Read : BOOL
VAR
	temp	: STRING;
	sstart,
	sNO,
	sAO,
	sGeneral,
	sWork	: STRING;

	pos		: INT;
	l		: INT;
END_VAR

ST.xhtml:
currentTime	:= Util.SysTimeRtc.SysTimeGetMs();
cycle		:= TO_REAL( currentTime - oldTime ) / hour_ms;

generalOpTime.set_value	:= generalOpTime.value + cycle * TO_BYTE( isStarted );
workOpTime.set_value	:= workOpTime.value + cycle * TO_BYTE( work );

oldTime	:= Util.SysTimeRtc.SysTimeGetMs();

