// класс расчёта итоговой величина параметра по двум входным значениям
// Chekmarev 24.04.2025
//  0.0.01
// коэффициенты с 
FUNCTION_BLOCK TFreqRotorHandler
VAR_INPUT
	ch		: ARRAY[1..2] OF REAL; // измеряемые каналы
	minVal	: REAL	:= 100.0;
	maxVal	: REAL;
	flt_prm	: BOOL := TRUE;	// разрешение на расчёт неисправности
	disbal_Ch	: REAL := 100.0; // максимальный дисбаланс между каналами
	disbal_t: REAL	:= 0.16;// время расчёта дисбаланса, сек
	ucvV	: REAL	:= 500;	// максимальное изменение входной величины за цикл
	deblock	: BOOL;			// деблокировка
END_VAR
VAR_OUTPUT
	flt		: ARRAY[1..2] OF BOOL;	// отказ каналов по диапазону
	fltUcv	: ARRAY[1..2] OF BOOL;	// отказ каналов по скорости изменения
	disbal	: BOOL;
END_VAR
VAR_IN_OUT
	out		: Tacpar;
END_VAR
VAR
	oldVal	: ARRAY[1..2] OF REAL;
	disbalTmr	: TON;	// таймер дисбаланса
	ucvTmr		: ARRAY[1..2] OF TOF;	// таймеры удержки признака высокой скорости изменения
END_VAR
VAR CONSTANT
	ms_to_s	: UINT 	:= 1_000;
	PTucvTmr: TIME	:= T#30S;	// время удержания ПС по скорости изменения входного значения
END_VAR

ST.xhtml:
flt_prm := flt_prm AND NOT deblock;

flt[1]	:= flt_prm AND ( ch[1] < minVal OR ch[1] > maxVal );
flt[2]	:= flt_prm AND ( ch[2] < minVal OR ch[2] > maxVal );

ucvTmr[1]( IN := flt_prm AND ABS( oldVal[1] - ch[1] ) > ucvV, PT := PTucvTmr );
ucvTmr[2]( IN := flt_prm AND ABS( oldVal[2] - ch[2] ) > ucvV, PT := PTucvTmr );

fltUcv[1] := ucvTmr[1].Q;
fltUcv[2] := ucvTmr[2].Q;

out.flt	:= ( flt[1] OR fltUcv[1] ) AND ( flt[2] OR fltUcv[2] );

IF ( ch[1] > ch[2] ) AND NOT ( flt[1] OR fltUcv[1] ) THEN
	out.in_value := ch[1];
	ELSIF NOT ( flt[2] OR fltUcv[2] ) THEN
	out.in_value := ch[2];
END_IF

disbalTmr (IN := flt_prm AND ( ABS( ch[1] - ch[2] ) > disbal_Ch ), PT := TO_TIME ( disbal_t * ms_to_s ));
disbal := disbalTmr.Q;

oldval[1] := ch[1];
oldVal[2] := ch[2];

